.showcase-admin{display:grid;gap:12px;margin-top:10px}.showcase-admin-grid{display:grid;grid-template-columns:minmax(180px,.72fr) minmax(0,1.28fr);gap:12px}.showcase-admin-drop{display:grid;place-items:center;min-height:210px;border:2px dashed #bfd4c5;border-radius:15px;background:transparent;padding:14px;text-align:center;transition:.16s ease;overflow:hidden}.showcase-admin-drop.drag{border-color:#168346;background:#eaf8ee;box-shadow:0 0 0 4px #16834612}.showcase-admin-drop img{width:100%;height:210px;object-fit:contain;object-position:center center;border-radius:11px}.showcase-admin-drop input{max-width:100%}.showcase-admin-copy textarea{width:100%;min-height:180px;padding:11px;border:1px solid #d4e3d7;border-radius:11px;resize:vertical;line-height:1.5}.showcase-mode{display:inline-flex;align-items:center;padding:5px 8px;border-radius:999px;background:#e8f6eb;color:#17673a;font-size:9px;font-weight:900}.showcase-mode.custom{background:#fff1c8;color:#755900}@media(max-width:720px){.showcase-admin-grid{grid-template-columns:1fr}}
