.admin-config-card{padding:0!important;overflow:hidden;align-self:start;min-width:0;max-width:100%;border-color:#d9e7dc!important;background:#fff!important;box-shadow:0 8px 30px rgba(25,68,39,.055)!important}
.admin-settings-toggle{width:100%;min-width:0;padding:15px 17px!important;border:0!important;border-radius:inherit;background:linear-gradient(145deg,#fff,#f7fbf8)!important;color:var(--ink);display:flex;align-items:center;justify-content:space-between;gap:12px;text-align:left;cursor:pointer;transition:background .16s ease,box-shadow .16s ease}
