.admin-settings-heading{display:flex;align-items:center;gap:9px;min-width:0;flex-wrap:wrap}.admin-settings-title{font-size:13px!important;font-weight:950;letter-spacing:-.01em;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.admin-settings-state{font-size:8px;font-weight:950;letter-spacing:.08em;text-transform:uppercase;padding:4px 6px;border-radius:999px;background:#edf4ef;color:#718078;white-space:nowrap}.admin-config-card.is-open .admin-settings-state{background:#dff4e5;color:#176a39}.admin-settings-chevron{display:grid;place-items:center;flex:0 0 28px;width:28px;height:28px;border-radius:9px;background:#edf4ef;color:#56705e;font-size:16px;transition:transform .16s ease,background .16s ease}.admin-config-card.is-open>.admin-settings-toggle .admin-settings-chevron{transform:rotate(180deg);background:#dff4e5;color:#176a39}
.admin-settings-body{margin:0!important;padding:16px 17px 18px!important;min-width:0!important;max-width:100%!important;border-top:1px solid #edf2ee}.admin-settings-body[hidden]{display:none!important}.admin-settings-body>*{min-width:0!important;max-width:100%}.admin-settings-body img,.admin-settings-body video,.admin-settings-body canvas,.admin-settings-body svg{max-width:100%}.admin-settings-body input,.admin-settings-body select,.admin-settings-body textarea,.admin-settings-body button{max-width:100%}
.grid{align-items:start!important;grid-auto-flow:row}.grid>.admin-config-card.is-open{grid-column:1/-1}.grid>.admin-config-card:not(.is-open){grid-column:auto}.admin-config-card.is-open{box-shadow:0 16px 44px rgba(25,68,39,.09)!important}
#modules .admin-settings-body,#globalModules .admin-settings-body{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 14px}#modules .admin-settings-body[hidden],#globalModules .admin-settings-body[hidden]{display:none!important}
.admin-tool{min-width:0!important;max-width:100%!important;overflow:hidden}.html-framer-list,.html-framer-row,.html-framer-controls,.html-framer-device-grid,.html-framer-device{min-width:0;max-width:100%}.html-framer-row-head{display:grid!important;grid-template-columns:auto auto auto minmax(180px,1fr) auto;align-items:center;gap:8px}.html-framer-row-head>.buttons{margin:0;justify-content:flex-end}.html-framer-row-title{min-width:0!important;width:100%}.html-framer-meta{overflow-wrap:anywhere}.html-framer-device-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
@media(max-width:900px){#modules .admin-settings-body,#globalModules .admin-settings-body,.html-framer-device-grid{grid-template-columns:1fr}.html-framer-row-head{grid-template-columns:repeat(3,auto) minmax(0,1fr)}.html-framer-row-head>.buttons{grid-column:1/-1;justify-content:flex-start}.html-framer-row-title{grid-column:1/-1;grid-row:2}}
@media(max-width:560px){.admin-settings-toggle{padding:13px 14px!important}.admin-settings-body{padding:14px!important}.admin-settings-title{white-space:normal}.html-framer-row-head{display:flex!important;align-items:stretch}.html-framer-row-head>.field-check{flex:1 1 auto}.html-framer-row-title{width:100%!important;min-width:100%!important}.html-framer-row-head>.buttons{width:100%;justify-content:flex-start}}

.html-framer-launch{display:grid;gap:10px;margin-top:10px;padding:13px;border:1px solid #d9e7dc;border-radius:14px;background:linear-gradient(145deg,#f8fcf9,#fff);min-width:0}.html-framer-launch-controls{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px;align-items:center}.html-framer-launch-controls select{width:100%;min-width:0;padding:10px 11px;border:1px solid #d4e3d7;border-radius:10px;background:#fff}.html-framer-launch-controls button{border:0;border-radius:10px;padding:10px 12px;font-weight:900;font-size:10px;cursor:pointer;white-space:nowrap}@media(max-width:680px){.html-framer-launch-controls{grid-template-columns:1fr}.html-framer-launch-controls button{width:100%}}

/* 0.15.75 production polish */
body.loom-admin-page{min-height:100vh;background:radial-gradient(circle at 16% -8%,rgba(169,223,79,.14),transparent 30%),radial-gradient(circle at 92% 0,rgba(39,158,56,.08),transparent 26%),linear-gradient(180deg,#f8fbf8,#eef5f0);overflow-x:hidden}
.loom-admin-page .wrap{width:min(1320px,calc(100% - 34px));margin:30px auto 70px}
.loom-admin-page .hero,.loom-admin-page .panel{border-color:rgba(51,103,65,.12);box-shadow:0 18px 58px rgba(18,54,29,.065),inset 0 1px rgba(255,255,255,.95)}
.loom-admin-page .hero{padding:28px;border-radius:28px}.loom-admin-page .panel{border-radius:22px}
.loom-admin-page .hero h1{font-size:clamp(38px,4vw,48px);line-height:1;letter-spacing:-.055em}.loom-admin-page .hero p,.loom-admin-page .panel p{font-size:12px;line-height:1.6}
.loom-admin-page .identity{gap:8px}.loom-admin-page .pill{min-height:27px;display:inline-flex;align-items:center;padding:6px 10px;border:1px solid rgba(22,131,70,.08)}
.loom-admin-page .toolbar{margin:20px 0 12px}.loom-admin-page .toolbar select{min-height:42px;border-radius:12px;border-color:rgba(51,103,65,.15);box-shadow:0 3px 12px rgba(18,54,29,.035)}
.loom-admin-page .tabs{padding:4px;border:1px solid rgba(51,103,65,.10);border-radius:15px;background:rgba(255,255,255,.56);box-shadow:0 4px 16px rgba(18,54,29,.025)}
.loom-admin-page .tab{min-height:40px;border-color:transparent;border-radius:11px;padding:9px 14px;background:transparent}.loom-admin-page .tab.active{background:#e6f4e9;color:#123f25;border-color:#b9d9c1;box-shadow:0 7px 18px rgba(23,63,39,.08)}
.loom-admin-page .grid{gap:16px}.loom-admin-page .module{border-color:rgba(51,103,65,.12);border-radius:20px;box-shadow:0 7px 25px rgba(18,54,29,.045)}
.loom-admin-page .admin-config-card.is-open{box-shadow:0 18px 48px rgba(18,54,29,.08)}
.loom-admin-page .field input,.loom-admin-page .field select,.loom-admin-page .field textarea{min-height:44px;border-radius:11px;border-color:rgba(51,103,65,.16);background:linear-gradient(180deg,#fff,#fbfdfb)}
.loom-admin-page .field textarea{padding:11px 12px}.loom-admin-page .field-check{min-height:44px;border-radius:11px;border-color:rgba(51,103,65,.14)}
.loom-admin-page .buttons button,.loom-admin-page .nav a{min-height:39px;display:inline-flex;align-items:center;justify-content:center;border-radius:10px;padding:9px 12px}
.loom-admin-page .save,.loom-admin-page .secondary{box-shadow:0 5px 15px rgba(23,63,39,.10)}
.loom-admin-page .empty{min-height:92px;display:grid;align-content:center;background:rgba(255,255,255,.62);border-radius:16px}
.loom-admin-page .danger-note{border-radius:14px}
@media(max-width:720px){.loom-admin-page .wrap{width:min(100% - 18px,1320px);margin-top:14px}.loom-admin-page .hero{padding:22px;border-radius:22px}.loom-admin-page .tabs{width:100%;overflow:auto;flex-wrap:nowrap}.loom-admin-page .tab{flex:0 0 auto}}

</style></head><body class="loom-admin-page"><div id="loomShellHeader"></div><div class="wrap">
<section class="hero"><div class="top"><div class="admin-brand-head"><div id="adminCube" class="admin-cube"></div><div><div class="eyebrow">LOOM v<span id="adminCanonicalVersion">0.15.58</span> · ADMINISTRATOR CONSOLE</div><h1>LOOM Admin</h1><p>Global LOOM configuration, project settings, user administration, moderation, and persistence.</p></div></div><div class="nav"><a id="appLink" href="#" aria-disabled="true">Open selected project</a></div></div><div class="identity"><span class="pill" id="who">Loading identity…</span><span class="pill">Privilege: Admin</span><span class="pill warn" id="storagePill">Checking storage…</span></div><div class="danger-note">User changes are auditable and require typing <b>CONFIRM</b>. IP addresses are captured as network metadata only; LOOM never uses IP as authentication proof or as the identity used for bans.</div></section>
<div class="toolbar"><div id="projectChooser" class="hidden"><strong>Project</strong> <select id="project"></select></div><div class="tabs"><button class="tab active" data-tab="loom">LOOM Settings</button><button class="tab" data-tab="project">Project Settings</button><button class="tab" data-tab="users">Users</button><button class="tab" data-tab="access">Access</button><button class="tab" data-tab="email">Email</button><button class="tab" data-tab="database">Database</button></div></div>
<section id="loomSettingsPanel" class="panel active"><div class="eyebrow">GLOBAL LOOM CORE SETTINGS</div><h2>LOOM Settings</h2><p>These settings belong to the LOOM engine itself and apply across LOOM-owned surfaces and all projects where relevant.</p><main id="globalModules" class="grid" style="margin-top:14px"></main></section>
<section id="projectSettingsPanel" class="panel"><div class="eyebrow">SELECTED PROJECT SETTINGS</div><h2>Project Settings</h2><p>Project identity is managed here; module configuration stays modular below it.</p><div id="projectSettingsEmpty" class="empty hidden" style="margin-top:14px"><b>No project exists yet.</b><br>Fresh LOOM intentionally ships without product projects. Create a new Instance Project from LOOM Home or import your exported project from Backup &amp; Restore.<div class="buttons"><a class="nav" style="text-decoration:none" href="../home/">Create Project</a><a class="nav" style="text-decoration:none" href="backups/">Import Project</a></div></div><div id="projectSettingsContent"><section id="projectPresentationCard" class="module" style="margin-top:14px" data-admin-static-section="project-presentation" data-admin-title="Module Presentation"></section><section class="module-control" data-admin-static-section="module-control" data-admin-title="Module Control Center"><div class="module-control-head"><div><div class="eyebrow">MODULE CONTROL CENTER</div><h2 style="margin:4px 0 3px">Every LOOM + project module</h2><p style="margin:0">Enable modules, control responsive loading, and optionally override each module’s title-bar/collapse behavior.</p></div><input id="moduleControlSearch" class="module-control-search" placeholder="Search modules, IDs, source…"></div><div id="moduleControlList" class="module-control-list"></div></section><section id="projectProfileCard" class="module" style="margin-top:14px" data-admin-static-section="project-profile" data-admin-title="Project Identity"></section><div class="eyebrow" style="margin-top:22px">PROJECT MODULE SETTINGS</div><main id="modules" class="grid" style="margin-top:10px"></main></div></section>
<section id="usersPanel" class="panel"><div class="eyebrow">PEOPLE &amp; IDENTITY</div><h2>Users</h2><p>One canonical people directory for all of LOOM. Start globally, or focus the exact same directory on a project to see only people with proven participation there. Guest vs permanent is a status—not a second user system.</p><div class="status-row user-directory-scope" style="margin-top:14px;align-items:center"><select id="usersScope" style="padding:10px 12px;border:1px solid #d4e4d7;border-radius:11px;background:#fff"><option value="">Global LOOM · All users</option></select><span id="userDirectoryCount" class="pill">0 users</span></div><div class="users-layout" style="margin-top:14px"><div><div class="user-search"><input id="identitySearch" placeholder="Search name, email, user ID, guest ID, IP or location"><select id="identityKindFilter" style="padding:10px;border:1px solid #d6e4d9;border-radius:10px"><option value="all">All people</option><option value="permanent">Permanent</option><option value="guest">Guests</option><option value="required">Permanent required</option><option value="banned">Banned</option></select><button id="identityRefresh" class="secondary user-refresh" type="button" title="Reload the current people directory"><span class="user-refresh-icon" aria-hidden="true">↻</span><span>Refresh</span></button></div><div id="identityList" class="user-list"></div></div><div id="identityDetail" class="user-detail"><div class="empty">Select a person.</div></div></div><section class="module" id="networkLocationCard" style="margin-top:18px"><div class="eyebrow">NETWORK CONTEXT · DISPLAY ONLY</div><h2>Prettified network locations</h2><p>LOOM can enrich public IP addresses into approximate city/region/country labels for Admin review. Location is never authentication proof and city/region/country never trigger guest overlap. Strict overlap uses bounded signals such as the same browser installation, matching device profile, exact shared IPv4, or the same IPv6 /64 household network. When remote enrichment is enabled, Admin detail lookups may send the public IP to the configured geolocation provider; results are cached and can be disabled or cleared here.</p><div class="profile-grid" style="grid-template-columns:minmax(220px,1fr) auto"><label class="field-check"><input id="geoRemoteEnabled" type="checkbox"><span>Enable cached public-IP geolocation enrichment</span></label><div class="buttons" style="margin:0"><button id="geoSave" class="secondary">Save</button><button id="geoClearCache" class="reset">Clear location cache</button></div></div><div id="geoStatus" class="msg"></div></section><section id="identityCleanupCard" class="module" style="margin-top:18px;border-color:#efb0b0;background:#fffafa"><div class="eyebrow" style="color:#9f2f2f">SYSTEM OWNER · PERMANENT DELETION</div><h2>Identity Cleanup &amp; Data Purge</h2><p>This tool permanently removes selected identity records. Preview first, choose exactly which storage/data layers to purge, then type the confirmation phrase. The System Owner is protected from ordinary deletion.</p><div id="identityCleanupOwner" class="status-row" style="margin:10px 0"></div><div id="identityMediaHygiene" class="setup" style="margin:10px 0"><b>Identity media hygiene</b><div id="identityMediaHygieneStatus" class="msg">Scanning for unowned avatar / Guest media…</div><div class="buttons" style="margin-top:8px"><button id="identityMediaScan" class="secondary" type="button">Scan orphan media</button><button id="identityMediaSweep" class="reset" type="button">Sweep orphan media…</button></div></div><div class="db-grid"><div class="field"><label>Target</label><select id="identityCleanupKind"><option value="guest-one">One Guest Identity</option><option value="user-one">One permanent account</option><option value="guests-all">All Guest Identities + orphan guest clients</option><option value="orphans-all">Legacy orphan client records only</option><option value="users-all">All permanent accounts except System Owner</option><option value="all-except-owner">All users + guests except System Owner</option><option value="factory-all">Factory identity wipe · includes System Owner</option></select></div><div class="field" id="identityCleanupSubjectWrap"><label>Identity</label><select id="identityCleanupSubject"></select></div><div class="field"><label>Storage to erase</label><select id="identityCleanupScope"><option value="both">Durable local + SQL database</option><option value="local">Durable local only</option><option value="database">SQL database only</option></select><div class="field-help">Database-only deletion can be restored later by local migration. Use Both for complete deletion when SQL is connected.</div></div></div><div class="profile-grid" style="grid-template-columns:repeat(auto-fit,minmax(230px,1fr));margin-top:8px"><label class="field-check"><input id="cleanupProjectData" type="checkbox" checked><span>Project identities, module state &amp; moderation</span></label><label class="field-check"><input id="cleanupActivity" type="checkbox" checked><span>Sessions, activity, presence &amp; replay</span></label><label class="field-check"><input id="cleanupReferrals" type="checkbox" checked><span>Referral shares &amp; attribution</span></label><label class="field-check"><input id="cleanupContinuity" type="checkbox" checked><span>Continuity, network &amp; ambiguity evidence</span></label><label class="field-check"><input id="cleanupMedia" type="checkbox" checked><span>Avatars &amp; identity media</span></label><label class="field-check"><input id="cleanupAudit" type="checkbox"><span>Audit history too · off by default</span></label><label class="field-check"><input id="cleanupAttachedGuests" type="checkbox"><span>When deleting users, also delete their attached Guest Histories</span></label></div><div class="buttons"><button id="identityCleanupPreview" class="secondary">Preview deletion</button><button id="identityCleanupExecute" class="danger" disabled>Delete permanently…</button></div><div id="identityCleanupPreviewOut" class="setup">Preview a deletion before anything can be removed.</div><div id="identityCleanupMsg" class="msg"></div></section></section>
<section id="accessPanel" class="panel"><div class="eyebrow">DELEGATED ADMINISTRATION</div><h2>Access Manager</h2><p>The System Owner is the immutable root authority. LOOM-wide Admin is global; Project Admin is always scoped to exactly one selected project.</p><div id="accessProjectContext" class="setup" style="margin-top:12px"></div><div id="accessSummary" class="status-row" style="margin-top:12px"></div><div class="grid" style="margin-top:14px"><section id="loomAdminAccessCard" class="module"><div class="eyebrow">LOOM-WIDE</div><h2>LOOM Admins</h2><p>Only the System Owner can add or revoke secondary LOOM Admins. They remain one tier below System Owner.</p><div class="field"><label>Permanent account</label><select id="loomAdminSubject"></select></div><div class="buttons"><button id="grantLoomAdmin" class="save">Grant LOOM Admin</button></div><div id="loomAdminList" class="setup"></div></section><section id="projectAdminAccessCard" class="module"><div class="eyebrow">PROJECT-SCOPED</div><h2>Project Admin</h2><p>Granting here applies only to the project shown above. It never grants access to unrelated projects or LOOM-global administration.</p><div class="field"><label>Account / Guest Identity</label><select id="projectAccessSubject"></select></div><div class="buttons"><button id="grantProjectAccess" class="save">Grant Project Admin</button></div><div id="projectAccessList" class="setup"></div></section></div><section id="projectPrivacyAccessCard" class="module" style="margin-top:14px"><div class="eyebrow">PROJECT VISIBILITY</div><div style="display:flex;gap:10px;align-items:center;justify-content:space-between;flex-wrap:wrap"><div><h2 style="margin-bottom:4px">Public / Private Project</h2><p style="margin:0">Public projects appear on LOOM Home for everyone. Private projects are omitted entirely unless the viewer is privileged or explicitly granted access.</p></div><span id="projectVisibilityPill" class="pill">🌐 Public</span></div><div class="buttons" style="margin-top:12px"><button id="toggleProjectVisibility" class="secondary" type="button">Make Private</button></div><div id="privateAccessControls" style="margin-top:14px"><div class="field"><label>Private project access · account / active guest</label><select id="privateAccessSubject"></select></div><div class="buttons"><button id="grantPrivateAccess" class="save" type="button">Grant Private Access</button></div><div id="privateAccessList" class="setup"></div></div></section><div id="accessMsg" class="msg"></div></section>

<section id="emailPanel" class="panel"><div class="eyebrow">GLOBAL SYSTEM EMAIL</div><h2>Email &amp; Account Recovery</h2><p>Configure one LOOM-wide outbound email transport for permanent-account notices, password recovery, and referral notifications. Settings are host-agnostic: use SMTP from any provider, or PHP mail() when your host explicitly supports it.</p><div id="emailStatus" class="status-row" style="margin-top:12px"></div><div class="grid" style="margin-top:14px"><section class="module"><div class="eyebrow">DELIVERY IDENTITY</div><h2>System sender</h2><div class="field"><label>Master delivery</label><label class="field-check"><input id="emailEnabled" type="checkbox"><span>Enable system email</span></label></div><div class="field"><label>Transport</label><select id="emailTransport"><option value="smtp">SMTP (recommended)</option><option value="php-mail">PHP mail()</option></select></div><div class="field"><label>Site / product name</label><input id="emailSiteName" type="text" value="LOOM"></div><div class="field"><label>Public base URL <span>required for Forgot Password</span></label><input id="emailBaseUrl" type="url" placeholder="https://example.com/loom"></div><div class="field"><label>From name</label><input id="emailFromName" type="text" value="LOOM"></div><div class="field"><label>From email</label><input id="emailFromEmail" type="email" placeholder="no-reply@example.com"></div><div class="field"><label>Reply-To <span>optional</span></label><input id="emailReplyTo" type="email" placeholder="support@example.com"></div><div class="field"><label>Email footer</label><textarea id="emailFooter"></textarea></div></section><section class="module" id="smtpCard"><div class="eyebrow">SMTP</div><h2>Server connection</h2><p class="desc">Use the SMTP details supplied by your email host. LOOM supports STARTTLS, implicit SSL/TLS, authenticated SMTP, and plain local SMTP.</p><div class="db-grid"><div class="field"><label>SMTP host</label><input id="smtpHost" type="text" placeholder="smtp.example.com"></div><div class="field"><label>Port</label><input id="smtpPort" type="number" value="587"></div><div class="field"><label>Encryption</label><select id="smtpEncryption"><option value="starttls">STARTTLS</option><option value="ssl">SSL / TLS</option><option value="none">None</option></select></div><div class="field"><label>Timeout (seconds)</label><input id="smtpTimeout" type="number" min="3" max="30" value="10"></div><div class="field"><label>Username</label><input id="smtpUsername" type="text" autocomplete="username"></div><div class="field"><label>Password</label><input id="smtpPassword" type="password" autocomplete="new-password" placeholder="Leave blank to keep saved password"></div></div><div class="field"><label>Authentication</label><label class="field-check"><input id="smtpAuth" type="checkbox" checked><span>SMTP server requires authentication</span></label></div></section><section class="module" style="grid-column:1/-1"><div class="eyebrow">STARTER EMAIL SUITE</div><h2>Notifications</h2><p class="desc">Each category can be independently disabled. Subject lines are editable; the secure LOOM body templates stay consistent and automatically include the site name and relevant action links.</p><div id="emailEvents" class="db-grid"></div></section><section class="module"><div class="eyebrow">SETUP DOCTOR</div><h2>Check configuration</h2><p class="desc">The status checker verifies required fields and server capabilities. SMTP Check Connection opens the socket, negotiates encryption, and authenticates without sending a message.</p><div class="buttons"><button id="emailSave" class="save">Save Email Settings</button><button id="emailProbe" class="secondary">Check Connection</button></div><div id="emailChecks" class="setup">Loading email configuration…</div><div id="emailMsg" class="msg"></div></section><section class="module"><div class="eyebrow">LIVE TEST</div><h2>Send a test email</h2><p class="desc">Use an address you can check. A successful transport response means the server accepted the message; final inbox placement is controlled by your email provider and DNS reputation.</p><div class="field"><label>Test recipient</label><input id="emailTestTo" type="email" placeholder="you@example.com"></div><div class="buttons"><button id="emailTest" class="secondary">Send Test Email</button></div><div class="setup"><b>Generic setup order</b><br>1. Create a mailbox or SMTP credential with your host/provider.<br>2. Enter host, port, encryption, username, and password here.<br>3. Set the public LOOM URL and a From address your provider permits.<br>4. Save, run Check Connection, then Send Test Email.<br>5. For reliable delivery, configure SPF/DKIM/DMARC in your domain DNS using the values supplied by your mail provider.</div></section><section class="module" style="grid-column:1/-1"><div class="eyebrow">DELIVERY ACTIVITY</div><h2>Recent system emails</h2><div id="emailRecent" class="setup">No email activity yet.</div></section></div></section>
<section id="databasePanel" class="panel"><div class="eyebrow">SQL PERSISTENCE</div><h2>MySQL / MariaDB</h2><p>Temporary files remain available before SQL connection. Once initialized/migrated, SQL is the durable persistence layer.</p><div id="dbStatus" class="status-row"></div><div class="db-grid"><div class="field"><label>Database host</label><input id="dbHost" type="text"></div><div class="field"><label>Port</label><input id="dbPort" type="number" value="3306"></div><div class="field"><label>Database name</label><input id="dbName" type="text"></div><div class="field"><label>Database username</label><input id="dbUser" type="text"></div><div class="field"><label>Password</label><input id="dbPass" type="password" placeholder="Leave blank to keep saved password"></div></div><div class="buttons"><button id="dbSave" class="save">1. Save & Test Connection</button><button id="dbInit" class="secondary">2. Initialize / Update Tables</button><button id="dbMigrate" class="secondary">3. Migrate Temporary Data</button></div><div id="dbMsg" class="msg"></div><div class="setup"><b>Existing database?</b> Running Initialize / Update Tables again is safe; LOOM schema updates use non-destructive <code>CREATE TABLE IF NOT EXISTS</code> statements where applicable.</div><div class="module" style="margin-top:16px"><div class="eyebrow">DATABASE INTEGRITY DOCTOR</div><h2>Audit before you repair</h2><p>Scans LOOM identity/account relationships without changing data. Safe Repair always creates a protected full LOOM-table snapshot first. It restores/validates the parent permanent-user row before repairing username, authentication, client, and Admin child mappings, then cleans expired login sessions. It never deletes user accounts, project history, events, avatars, or moderation records.</p><div class="buttons"><button id="integrityScan" class="secondary">Scan Integrity</button><button id="integrityBackup" class="reset">Create Snapshot</button><button id="integrityRepair" class="danger">Safe Repair…</button></div><div id="integritySummary" class="status-row" style="margin-top:12px"></div><div id="integrityIssues" class="setup">Run a scan to inspect the database.</div><div id="integrityMsg" class="msg"></div></div></section>
