async function adminFetchJson(url,options={},label='LOOM API',attempts=1){
  const now=Date.now();if(now<adminApiCooldownUntil){const seconds=Math.max(1,Math.ceil((adminApiCooldownUntil-now)/1000));throw new Error(`${label}: server is temporarily busy. LOOM paused additional Admin requests for ${seconds}s instead of retrying in a loop.`)}
  const method=String(options.method||'GET').toUpperCase();let bodyKey='';if(typeof options.body==='string')bodyKey=options.body;else if(options.body instanceof FormData){bodyKey=[...options.body.entries()].map(([k,v])=>v instanceof File?`${k}:${v.name}:${v.size}`:`${k}:${String(v)}`).join('|')}else bodyKey='[binary]';const key=`${method} ${url} ${bodyKey}`;
  if(adminApiInflight.has(key))return adminApiInflight.get(key);
  const task=(async()=>{let last=null;const networkAttempts=Math.max(1,Math.min(2,Number(attempts)||1));for(let i=0;i<networkAttempts;i++){try{
    const r=await fetch(url,{cache:'no-store',...options});
    if(r.status===503){const retry=Math.max(2,Math.min(10,Number(r.headers.get('Retry-After')||4)));adminApiCooldownUntil=Date.now()+retry*1000;const raw=await r.text().catch(()=>''),clean=raw.replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim().slice(0,120);const e=new Error(`${label}: server temporarily busy (503). No retry storm was started.${clean?` ${clean}`:''}`);e.httpStatus=503;throw e}
