    card.querySelector('[data-showcase-upload]')?.addEventListener('click',()=>{const f=input?.files?.[0];if(f)showcaseUpload(card,f);else input?.click()});
    input?.addEventListener('change',()=>{const f=input.files?.[0];if(f)showcaseUpload(card,f)});
