async function htmlFramerRequest(action,opts={}){
  const project=$('#project').value;
  if(opts.file){
    const fd=new FormData();fd.append('action',action);fd.append('project',project);fd.append('clientId',identity.clientId);fd.append('zip',opts.file,opts.file.name);
    if(opts.entrypoint)fd.append('entrypoint',opts.entrypoint);if(opts.replaceId)fd.append('replaceId',opts.replaceId);
    return adminFetchJson('../api/html-framer.php',{method:'POST',body:fd},'HTML Framer',1)
  }
  if(action==='list')return adminFetchJson(`../api/html-framer.php?action=list&project=${encodeURIComponent(project)}&clientId=${encodeURIComponent(identity.clientId)}&_=${Date.now()}`,{},'HTML Framer',1);
  return adminFetchJson('../api/html-framer.php',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({action,project,clientId:identity.clientId,...opts})},'HTML Framer',1)
}
function htmlFramerAnalysisHtml(a){
  if(!a)return '';
  const size=Math.round((a.totalBytes||0)/1024);
  const repairs=(a.repairs||[]).length,missing=(a.missingRefs||[]).length,warns=[...(a.warnings||[])];
  if(missing)warns.push(`${missing} local reference${missing===1?'':'s'} could not be resolved automatically.`);
  const reader=a.actionReader||{},readerText=`${esc(reader.trackableCount||0)} trackable UI action${Number(reader.trackableCount||0)===1?'':'s'} · ${esc(reader.functionCandidateCount||0)} JS function candidate${Number(reader.functionCandidateCount||0)===1?'':'s'} · ${esc(reader.listenerEventCount||0)} listener registration${Number(reader.listenerEventCount||0)===1?'':'s'}`;
  return `<div class="html-framer-analysis"><b>${esc(a.fileCount||0)} files · ${esc(a.cssCount||0)} CSS · ${esc(a.jsCount||0)} JS · ${esc(size)} KB</b><br><b>Action Reader:</b> ${readerText}. ${(reader.functionCandidateCount||0)?'Function names are discovery hints; LOOM tracks observable user interactions without wrapping arbitrary foreign functions. ':''}${repairs?`${esc(repairs)} safe path repair${repairs===1?'':'s'} detected. `:''}${(a.autoAttachCss||[]).length?`${esc(a.autoAttachCss.length)} CSS root${a.autoAttachCss.length===1?'':'s'} will be auto-attached. `:''}${(a.autoAttachJs||[]).length?`${esc(a.autoAttachJs.length)} JS root${a.autoAttachJs.length===1?'':'s'} will be auto-attached.`:''}${warns.length?`<div class="html-framer-warnings">${warns.slice(0,8).map(x=>esc(x)).join('<br>')}</div>`:''}</div>`
}
function htmlFramerLaunchHtml(data){
  const frames=data?.frames||[],selected=String(data?.autoFullscreenFrameId||'');
  return `<div class="html-framer-launch"><div><b>Project launch full screen</b><div class="msg">Optional · off by default. Choose one installed HTML frame to take over the page automatically when this project loads. Manual Exit full screen always returns to LOOM.</div></div><div class="html-framer-launch-controls"><select data-hf-auto-fullscreen><option value="">Off · show normal LOOM project page</option>${frames.map(f=>`<option value="${esc(f.id)}" ${selected===String(f.id)?'selected':''}>${esc(f.title||f.id)}${f.enabled===false?' · not live':''}${f.fullscreenEnabled===false?' · full screen disabled':''}</option>`).join('')}</select><button class="secondary" data-hf-auto-save>Save launch behavior</button></div><div class="field-help">If the selected frame is later disabled, deleted, or has full-screen permission turned off, LOOM safely falls back to the normal project page.</div></div>`;
}
function htmlFramerRows(frames){
  if(!frames?.length)return '<div class="html-framer-empty">No HTML frame modules yet. Drop a ZIP above to create one.</div>';
  const modeOptions=v=>`<option value="auto" ${v!=='fixed'?'selected':''}>Stretch to delivered content</option><option value="fixed" ${v==='fixed'?'selected':''}>Fixed height + scrolling</option>`;
  return `<div class="html-framer-list">${frames.map((f,i)=>{const dm=f.heightMode==='fixed'?'fixed':'auto',mm=f.mobileHeightMode==='fixed'?'fixed':'auto',dh=Number(f.height||520),mh=Number(f.mobileHeight||f.height||520),dw=Number(f.widthPercent??80),mw=Number(f.mobileWidthPercent??f.widthPercent??80),fs=f.fullscreenEnabled!==false,il=f.interactionLockEnabled===true;return `<div class="html-framer-row" data-hf-id="${esc(f.id)}"><div class="html-framer-row-head"><label class="field-check"><input type="checkbox" data-hf-enabled ${f.enabled!==false?'checked':''}><span>Live</span></label><label class="field-check"><input type="checkbox" data-hf-track ${f.actionReaderEnabled!==false?'checked':''}><span>Track actions</span></label><label class="field-check"><input type="checkbox" data-hf-fullscreen ${fs?'checked':''}><span>Allow full screen</span></label><label class="field-check"><input type="checkbox" data-hf-lock ${il?'checked':''}><span>Start locked</span></label><input class="html-framer-row-title" data-hf-title value="${esc(f.title||'HTML Frame')}"><div class="buttons" style="margin:0"><button class="reset" data-hf-move="up" ${i===0?'disabled':''}>↑</button><button class="reset" data-hf-move="down" ${i===frames.length-1?'disabled':''}>↓</button><button class="danger" data-hf-delete>Delete</button></div></div><div class="html-framer-meta"><code>${esc(f.id)}</code> · entry <code>${esc(f.entrypoint||'')}</code> · ${esc(f.fileCount||0)} files · revision ${esc(f.revision||1)}${f.zipName?` · ${esc(f.zipName)}`:''} · Action Reader ${f.actionReaderEnabled===false?'off':`${esc(f.actionReader?.trackableCount||0)} cataloged`}</div><div class="html-framer-controls"><div class="html-framer-device-grid"><section class="html-framer-device"><h4>Desktop / tablet</h4><div class="field"><label>Height behavior</label><select data-hf-height-mode>${modeOptions(dm)}</select></div><div class="field" data-hf-fixed-wrap ${dm==='fixed'?'':'hidden'}><label>Fixed height <span data-hf-height-value>${esc(dh)}px</span></label><input data-hf-height type="range" min="200" max="2400" step="10" value="${esc(dh)}"></div><div class="field"><label>Page width <span data-hf-width-value>${esc(dw)}%</span></label><input data-hf-width type="range" min="50" max="100" step="1" value="${esc(dw)}"></div>${dm==='auto'?'<div class="html-framer-autofit-note">Smart auto-fit is active: ordinary documents grow to content while viewport-style apps/games keep one stable viewport and their own intentional internal layout.</div>':''}</section><section class="html-framer-device"><h4>Mobile ≤ 760px</h4><div class="field"><label>Height behavior</label><select data-hf-mobile-height-mode>${modeOptions(mm)}</select></div><div class="field" data-hf-mobile-fixed-wrap ${mm==='fixed'?'':'hidden'}><label>Fixed height <span data-hf-mobile-height-value>${esc(mh)}px</span></label><input data-hf-mobile-height type="range" min="200" max="2400" step="10" value="${esc(mh)}"></div><div class="field"><label>Page width <span data-hf-mobile-width-value>${esc(mw)}%</span></label><input data-hf-mobile-width type="range" min="50" max="100" step="1" value="${esc(mw)}"></div>${mm==='auto'?'<div class="html-framer-autofit-note">Mobile smart auto-fit is independent: responsive document flow is remeasured while viewport-style mobile apps keep their intentional internal layout.</div>':''}</section></div><div class="html-framer-autofit-note">Every frame now has a runtime <b>Lock frame</b> control beside Full screen. <b>Start locked</b> is the optional boot preference: when enabled, the frame opens shielded so wheel/touch scrolls LOOM normally until the centered Unlock button is used.</div><div class="html-framer-savebar"><button class="save" data-hf-save>Save Frame Presentation</button></div></div>${(f.warnings||[]).length||(f.missingRefs||[]).length?`<div class="html-framer-warnings">${[...(f.warnings||[]),...((f.missingRefs||[]).slice(0,5).map(x=>`Unresolved: ${x.from} → ${x.raw}`))].slice(0,8).map(x=>esc(x)).join('<br>')}</div>`:''}</div>`}).join('')}</div>`
}
async function htmlFramerLoad(node){
  try{const data=await htmlFramerRequest('list');node._hfData=data;htmlFramerRender(node)}catch(e){node.innerHTML=`<div class="html-framer-warnings">${esc(e.message)}</div>`}
}
function htmlFramerRender(node){
  const data=node._hfData||{frames:[]},a=node._hfAnalysis||null,candidates=a?.htmlCandidates||[],needs=!!a?.needsEntrypoint;
  node.innerHTML=`<div class="html-framer-drop" data-hf-drop><b>Drop one HTML package ZIP here</b><div class="msg">LOOM preserves valid links, discovers dependencies and auto-attaches orphan CSS/JS roots.</div><input data-hf-file type="file" accept=".zip,application/zip">${needs?`<div class="field"><label>Multiple HTML files found · choose the entrypoint</label><select data-hf-entry>${candidates.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select></div>`:''}<div class="buttons"><button class="secondary" data-hf-analyze>Analyze ZIP</button><button class="save" data-hf-publish ${!node._hfFile?'disabled':''}>${needs?'Publish Selected Entrypoint':'Publish Frame Module'}</button></div>${htmlFramerAnalysisHtml(a)}</div><div class="admin-tool" style="margin-top:10px"><b>Capture Static URL</b><div class="msg">Enter an http/https page. LOOM downloads a bounded, same-origin static snapshot into the Instance Vault. It is not a live production embed and does not stay synchronized.</div><div class="field"><label>Web page URL</label><input data-hf-url type="url" placeholder="https://example.com/page"></div><div class="buttons"><button class="secondary" data-hf-capture>Capture URL → Static Frame</button></div><div class="msg" data-hf-capture-msg></div></div>${htmlFramerLaunchHtml(data)}${htmlFramerRows(data.frames||[])}`;
  const drop=node.querySelector('[data-hf-drop]'),fileInput=node.querySelector('[data-hf-file]');
  const choose=async file=>{if(!file)return;node._hfFile=file;try{const r=await htmlFramerRequest('analyze',{file});node._hfAnalysis=r.analysis;htmlFramerRender(node)}catch(e){node._hfAnalysis={warnings:[e.message]};htmlFramerRender(node)}};
  fileInput.onchange=()=>choose(fileInput.files?.[0]);
  drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');const f=e.dataTransfer.files?.[0];if(f)choose(f)};
  node.querySelector('[data-hf-analyze]').onclick=()=>choose(node._hfFile||fileInput.files?.[0]);
  node.querySelector('[data-hf-publish]').onclick=async()=>{const file=node._hfFile;if(!file)return;const entry=node.querySelector('[data-hf-entry]')?.value||node._hfAnalysis?.entrypoint||'';try{const r=await htmlFramerRequest('upload',{file,entrypoint:entry});if(r.needsEntrypoint){node._hfAnalysis=r.analysis;htmlFramerRender(node);return}node._hfFile=null;node._hfAnalysis=null;node._hfData=r;htmlFramerRender(node)}catch(e){alert(e.message)}};
  node.querySelector('[data-hf-capture]')?.addEventListener('click',async()=>{const url=node.querySelector('[data-hf-url]')?.value?.trim(),msg=node.querySelector('[data-hf-capture-msg]');if(!url)return;msg.textContent='Capturing static snapshot…';try{const r=await htmlFramerRequest('capture-url',{url});node._hfData=r;msg.textContent=r.message||'Static snapshot imported.';htmlFramerRender(node)}catch(e){msg.textContent=e.message}});
  node.querySelectorAll('[data-hf-height]').forEach(el=>el.oninput=()=>{el.closest('.html-framer-row').querySelector('[data-hf-height-value]').textContent=`${el.value}px`});node.querySelectorAll('[data-hf-width]').forEach(el=>el.oninput=()=>{el.closest('.html-framer-row').querySelector('[data-hf-width-value]').textContent=`${el.value}%`});node.querySelectorAll('[data-hf-mobile-height]').forEach(el=>el.oninput=()=>{el.closest('.html-framer-row').querySelector('[data-hf-mobile-height-value]').textContent=`${el.value}px`});node.querySelectorAll('[data-hf-mobile-width]').forEach(el=>el.oninput=()=>{el.closest('.html-framer-row').querySelector('[data-hf-mobile-width-value]').textContent=`${el.value}%`});
  node.querySelectorAll('[data-hf-height-mode]').forEach(el=>el.onchange=()=>{el.closest('.html-framer-device').querySelector('[data-hf-fixed-wrap]').hidden=el.value!=='fixed'});node.querySelectorAll('[data-hf-mobile-height-mode]').forEach(el=>el.onchange=()=>{el.closest('.html-framer-device').querySelector('[data-hf-mobile-fixed-wrap]').hidden=el.value!=='fixed'});
  node.querySelector('[data-hf-auto-save]')?.addEventListener('click',async()=>{try{const selected=node.querySelector('[data-hf-auto-fullscreen]')?.value||'';node._hfData=await htmlFramerRequest('set-auto-fullscreen',{frameId:selected});htmlFramerRender(node);toastOk(selected?'Project launch full screen saved.':'Automatic full screen is off.')}catch(e){alert(e.message)}});
  node.querySelectorAll('[data-hf-save]').forEach(btn=>btn.onclick=async()=>{const row=btn.closest('[data-hf-id]');try{node._hfData=await htmlFramerRequest('update',{frameId:row.dataset.hfId,title:row.querySelector('[data-hf-title]').value,enabled:row.querySelector('[data-hf-enabled]').checked,actionReaderEnabled:row.querySelector('[data-hf-track]').checked,heightMode:row.querySelector('[data-hf-height-mode]').value,height:Number(row.querySelector('[data-hf-height]').value),widthPercent:Number(row.querySelector('[data-hf-width]').value),mobileHeightMode:row.querySelector('[data-hf-mobile-height-mode]').value,mobileHeight:Number(row.querySelector('[data-hf-mobile-height]').value),mobileWidthPercent:Number(row.querySelector('[data-hf-mobile-width]').value),fullscreenEnabled:row.querySelector('[data-hf-fullscreen]').checked,interactionLockEnabled:row.querySelector('[data-hf-lock]').checked});htmlFramerRender(node);toastOk('HTML frame presentation, interaction lock, and full-screen access saved.')}catch(e){alert(e.message)}});
  node.querySelectorAll('[data-hf-move]').forEach(btn=>btn.onclick=async()=>{const row=btn.closest('[data-hf-id]');try{node._hfData=await htmlFramerRequest('move',{frameId:row.dataset.hfId,direction:btn.dataset.hfMove});htmlFramerRender(node)}catch(e){alert(e.message)}});
  node.querySelectorAll('[data-hf-delete]').forEach(btn=>btn.onclick=async()=>{const row=btn.closest('[data-hf-id]');if(!confirm('Delete this HTML frame module and its stored ZIP/files?'))return;try{node._hfData=await htmlFramerRequest('delete',{frameId:row.dataset.hfId});htmlFramerRender(node)}catch(e){alert(e.message)}});
}
function bindHtmlFramerManagers(scope){scope.querySelectorAll('[data-html-framer-manager]').forEach(node=>htmlFramerLoad(node))}

function renderProjectPresentation(){const box=$('#projectPresentationCard'),p=state?.project_presentation||{};if(!box)return;box.innerHTML=`<div class="eyebrow">PROJECT CHROME</div><h2>Module title bars + collapse</h2><div class="desc">Set the project-wide behavior here. Every project module can still override these three choices individually in Module Control Center.</div><div class="project-presentation-grid"><div class="field"><label>Collapse capability</label><select id="projectCollapseMode"><option value="inherit" ${p.collapseMode==='inherit'?'selected':''}>Inherit LOOM global (${p.globalDefaults?.collapseEnabled?'enabled':'disabled'})</option><option value="enabled" ${p.collapseMode==='enabled'?'selected':''}>Enabled</option><option value="disabled" ${p.collapseMode==='disabled'?'selected':''}>Completely disabled</option></select></div><div class="field"><label>Module title bars</label><select id="projectTitleBarMode"><option value="inherit" ${p.titleBarMode==='inherit'?'selected':''}>Inherit LOOM global (${p.globalDefaults?.titleBarsEnabled?'shown':'hidden'})</option><option value="show" ${p.titleBarMode==='show'?'selected':''}>Show</option><option value="hide" ${p.titleBarMode==='hide'?'selected':''}>Hide</option></select></div><div class="field"><label>Initial module state</label><select id="projectInitialState"><option value="inherit" ${p.initialState==='inherit'?'selected':''}>Inherit LOOM global (${esc(p.globalDefaults?.initialState||'expanded')})</option><option value="expanded" ${p.initialState==='expanded'?'selected':''}>Expanded</option><option value="collapsed" ${p.initialState==='collapsed'?'selected':''}>Collapsed</option></select></div></div><div class="buttons"><button class="save" id="saveProjectPresentation">Save Project Presentation</button></div><div class="msg">Current effective behavior: title bars ${p.titleBarsEnabled?'shown':'hidden'} · collapse ${p.collapseEnabled?'enabled':'disabled'} · first visit ${esc(p.effectiveInitialState||'expanded')}.</div>`;$('#saveProjectPresentation').onclick=async()=>{try{state=await post({action:'module-presentation-save',project:$('#project').value,presentation:{collapseMode:$('#projectCollapseMode').value,titleBarMode:$('#projectTitleBarMode').value,initialState:$('#projectInitialState').value}});renderProjectPresentation();renderModuleControl();renderModules();decorateProjectStaticCards();toastOk('Project module presentation updated.')}catch(e){toastErr(e.message)}};decorateProjectStaticCards()}
function renderModuleControl(){
  const list=$('#moduleControlList'),q=($('#moduleControlSearch')?.value||'').trim().toLowerCase(),catalog=state?.module_catalog||[];
  if(!list)return;
  const rows=catalog.filter(m=>!q||[m.name,m.actionId,m.source,m.scope].some(v=>String(v||'').toLowerCase().includes(q)));
  list.innerHTML=rows.length?rows.map(m=>{
    const projectScoped=m.scope==='project',mobileSupported=m.mobileVisibilitySupported!==false&&projectScoped,c=m.chrome||{};
    const defaultPositionNote=m.positionSource==='default'&&m.positionDefault!=null?(m.positionIndex!==m.positionDefault?` · default ${m.positionDefault} → resolved ${m.positionIndex}`:` · default ${m.positionDefault}`):'';
    const position=projectScoped&&m.positionSupported!==false?`<label class="module-position-control" title="1 is the first normal module. LOOM defaults Header to 1, Showcase to 2, and Footer to 99. Explicit project choices outrank those soft defaults. If another explicit module already owns a number, LOOM advances to the next free slot."><span>Positioning Index Number${defaultPositionNote}</span><input class="module-position-index" type="number" min="1" step="1" inputmode="numeric" value="${m.positionIndex??''}" placeholder="Auto"></label>`:'';
    const chrome=projectScoped?`<div class="module-chrome-controls"><label>Collapse<select data-chrome="collapseMode"><option value="inherit" ${c.collapseMode==='inherit'?'selected':''}>Inherit project</option><option value="enabled" ${c.collapseMode==='enabled'?'selected':''}>Enabled</option><option value="disabled" ${c.collapseMode==='disabled'?'selected':''}>Disabled</option></select></label><label>Title bar<select data-chrome="titleBarMode"><option value="inherit" ${c.titleBarMode==='inherit'?'selected':''}>Inherit project</option><option value="show" ${c.titleBarMode==='show'?'selected':''}>Show</option><option value="hide" ${c.titleBarMode==='hide'?'selected':''}>Hide</option></select></label><label>Title text<input data-chrome-text="titleText" maxlength="100" value="${esc(c.titleText||'')}" placeholder="Default: ${esc(m.name)}"></label><label>Initial state<select data-chrome="initialState"><option value="inherit" ${c.initialState==='inherit'?'selected':''}>Inherit project</option><option value="expanded" ${c.initialState==='expanded'?'selected':''}>Expanded</option><option value="collapsed" ${c.initialState==='collapsed'?'selected':''}>Collapsed</option></select></label></div>`:'';
    return `<div class="module-control-row" data-control-module="${esc(m.actionId)}" data-control-scope="${esc(m.scope)}"><label class="module-control-switch" title="${m.enabled?'Disable':'Enable'} ${esc(m.name)}"><input class="module-enabled-toggle" type="checkbox" ${m.enabled?'checked':''} ${m.locked?'disabled':''}><span></span></label><div class="module-control-name"><strong>${esc(m.name)}</strong><small>${esc(m.actionId)} · ${esc(m.description||'')}</small></div><span class="module-control-badge">${esc(m.scope)} · ${esc(m.source)}</span>${position}${mobileSupported?`<label class="module-mobile-control"><input class="module-mobile-toggle" type="checkbox" ${m.hideOnMobile?'checked':''}><span>Hide on mobile</span></label>`:`<span class="module-mobile-control disabled">Desktop + mobile</span>`}<span class="module-control-status">${m.enabled?'Enabled':'Disabled'}</span>${chrome}</div>`;
  }).join(''):'<div class="empty" style="margin:12px">No matching modules.</div>';
  list.querySelectorAll('[data-control-module] .module-enabled-toggle').forEach(el=>el.onchange=async()=>{const row=el.closest('[data-control-module]'),status=row.querySelector('.module-control-status');status.textContent='Saving…';el.disabled=true;try{const d=await post({action:'module-toggle',project:$('#project').value,moduleId:row.dataset.controlModule,scope:row.dataset.controlScope,enabled:el.checked});if(row.dataset.controlScope==='global'){globalState=d;state=await post({action:'settings',project:$('#project').value})}else state=d;renderProjectPresentation();renderModuleControl();renderModules();if(row.dataset.controlScope==='global')renderGlobalModules();toastOk(`${row.dataset.controlModule} ${el.checked?'enabled':'disabled'}.`,'Module updated')}catch(e){el.checked=!el.checked;el.disabled=false;status.textContent=e.message;toastErr(e.message)}});
  list.querySelectorAll('[data-control-module] .module-mobile-toggle').forEach(el=>el.onchange=async()=>{const row=el.closest('[data-control-module]'),status=row.querySelector('.module-control-status');status.textContent='Saving…';el.disabled=true;try{state=await post({action:'module-mobile-visibility',project:$('#project').value,moduleId:row.dataset.controlModule,scope:row.dataset.controlScope,hideOnMobile:el.checked});renderModuleControl();renderModules();toastOk(`${row.dataset.controlModule} mobile visibility applied.`,'Module updated')}catch(e){el.checked=!el.checked;el.disabled=false;status.textContent=e.message;toastErr(e.message)}});
  list.querySelectorAll('[data-control-module] .module-position-index').forEach(el=>el.addEventListener('input',()=>{clearTimeout(el._loomPositionTimer);const row=el.closest('[data-control-module]'),status=row.querySelector('.module-control-status'),raw=el.value.trim();if(raw!==''&&(!/^\d+$/.test(raw)||Number(raw)<1)){status.textContent='Use 1+ or blank';el.setAttribute('aria-invalid','true');return}el.removeAttribute('aria-invalid');status.textContent='Checking…';el._loomPositionTimer=setTimeout(async()=>{const requested=raw===''?null:Number(raw);try{const d=await post({action:'module-position-index',project:$('#project').value,moduleId:row.dataset.controlModule,positionIndex:requested});const r=d.positionResolution||{};state=d;if(r.resolved==null){el.value='';status.textContent='Automatic';toastOk(`${row.dataset.controlModule} returned to deterministic automatic ordering.`,'Module position')}else{el.value=String(r.resolved);if(r.revertedToDefault){status.textContent=`Default ${r.resolved}`;toastOk(`${row.dataset.controlModule} returned to its LOOM default position ${r.resolved}.`,'Module position')}else if(r.autoIterated){status.textContent=`Position ${r.resolved}`;toastInfo(`Position ${r.requested} was already used${r.collisionWith?` by ${r.collisionWith}`:''}. LOOM resolved this module to ${r.resolved}, the next available slot.`,'Position collision resolved')}else{status.textContent=`Position ${r.resolved}`;toastOk(`${row.dataset.controlModule} set to position ${r.resolved}.`,'Module position')}}renderModuleControl();renderModules()}catch(e){status.textContent=e.message;toastErr(e.message)}},350)}));
  list.querySelectorAll('[data-control-module] [data-chrome],[data-control-module] [data-chrome-text]').forEach(el=>el.onchange=async()=>{const row=el.closest('[data-control-module]'),status=row.querySelector('.module-control-status'),payload={};row.querySelectorAll('[data-chrome]').forEach(x=>payload[x.dataset.chrome]=x.value);row.querySelectorAll('[data-chrome-text]').forEach(x=>payload[x.dataset.chromeText]=x.value);status.textContent='Saving…';try{state=await post({action:'module-presentation-override',project:$('#project').value,moduleId:row.dataset.controlModule,presentation:payload});renderProjectPresentation();renderModuleControl();renderModules();toastOk(`${row.dataset.controlModule} title/collapse behavior updated.`,'Module presentation')}catch(e){status.textContent=e.message;toastErr(e.message)}});
  decorateProjectStaticCards();
}

function renderModules(){const box=$('#modules'),mods=state?.modules||[];box.innerHTML=mods.map(m=>{const fields=m.admin_settings?.fields||[];return `<section class="module" data-module="${esc(m.actionId)}" data-admin-config-card="${esc(m.actionId)}" data-admin-title="${esc(m.admin_settings?.title||m.name)}"><div class="eyebrow">${m.source==='core-project'?'CORE PROJECT · ':''}${esc(m.order)} · ${esc(m.actionId)}</div><h2>${esc(m.admin_settings?.title||m.name)}</h2><div class="desc">${esc(m.admin_settings?.description||m.description)}</div>${fields.map(f=>fieldHtml(f,m.values?.[f.id]??m.defaults?.[f.id])).join('')}${(m.admin_settings?.tools||[]).map(t=>toolHtml(t,m)).join('')}${fields.length?`<div class="buttons"><button class="save" data-save data-loom-tip="Apply these module settings to the selected project. A toast confirms the saved state.">Save</button><button class="reset" data-reset data-loom-tip="Remove project overrides for this module and restore its defaults.">Reset defaults</button></div>`:''}<div class="msg" data-msg></div></section>`}).join('');box.querySelectorAll('input[type=range]').forEach(el=>el.oninput=()=>{const f=mods.flatMap(x=>x.admin_settings?.fields||[]).find(x=>x.id===el.dataset.field),out=box.querySelector(`[data-value="${CSS.escape(el.dataset.field)}"]`);if(out)out.textContent=el.value+(f?.unit||'')});bindConditionalFields(box);bindHtmlFramerManagers(box);bindShowcaseManagers(box);bindSocialLinkHelpers(box);box.querySelectorAll('[data-save]').forEach(btn=>btn.onclick=async()=>{const card=btn.closest('.module'),m=mods.find(x=>x.actionId===card.dataset.module),vals={};for(const f of m.admin_settings.fields){const el=card.querySelector(`[data-field="${CSS.escape(f.id)}"]`);vals[f.id]=readAdminField(el,f)}try{state=await post({action:'save',project:$('#project').value,moduleId:card.dataset.module,values:vals});renderModules();toastOk(`${m.admin_settings?.title||m.name} settings applied.`)}catch(e){card.querySelector('[data-msg]').textContent=e.message;toastErr(e.message)}});box.querySelectorAll('[data-reset]').forEach(btn=>btn.onclick=async()=>{const card=btn.closest('.module');try{state=await post({action:'reset',project:$('#project').value,moduleId:card.dataset.module});renderModules();toastOk('Module defaults restored.','Defaults restored')}catch(e){card.querySelector('[data-msg]').textContent=e.message;toastErr(e.message)}});box.querySelectorAll('[data-config-preset]').forEach(btn=>btn.onclick=async()=>{const card=btn.closest('.module');try{state=await post({action:'apply-preset',project:$('#project').value,moduleId:card.dataset.module,presetId:btn.dataset.configPreset});renderModules();toastOk('Module preset applied.','Preset applied')}catch(e){card.querySelector('[data-msg]').textContent=e.message;toastErr(e.message)}});box.querySelectorAll('[data-favicon-upload]').forEach(btn=>btn.onclick=async()=>{const card=btn.closest('.module'),file=card.querySelector('[data-favicon-file]')?.files?.[0];if(!file)return;try{state=await post({action:'favicon-upload',project:$('#project').value,moduleId:card.dataset.module,pngBase64:await imageFileToPngDataUrl(file)});renderModules()}catch(e){card.querySelector('[data-msg]').textContent=e.message}});box.querySelectorAll('[data-favicon-logo]').forEach(btn=>btn.onclick=async()=>{const card=btn.closest('.module');try{state=await post({action:'favicon-use-logo',project:$('#project').value,moduleId:card.dataset.module});renderModules()}catch(e){card.querySelector('[data-msg]').textContent=e.message}});box.querySelectorAll('[data-emoji-toggle]').forEach(btn=>btn.onclick=()=>btn.closest('.orb-admin-row').querySelector('.emoji-pop')?.classList.toggle('open'));box.querySelectorAll('[data-emoji-value]').forEach(btn=>btn.onclick=()=>{const row=btn.closest('.orb-admin-row');row.querySelector('[data-orb-emoji]').value=btn.dataset.emojiValue;row.querySelector('.emoji-pop').classList.remove('open')});box.querySelectorAll('[data-orb-save]').forEach(btn=>btn.onclick=async()=>{const card=btn.closest('.module'),targets={};card.querySelectorAll('[data-orb-target]').forEach(row=>{targets[row.dataset.orbTarget]={captured:!!row.querySelector('[data-orb-captured]').checked,emoji:row.querySelector('[data-orb-emoji]').value.trim()}});try{state=await post({action:'orb-save',project:$('#project').value,moduleId:card.dataset.module,targets});renderModules()}catch(e){card.querySelector('[data-msg]').textContent=e.message}});decorateRenderedCards(box,'project-modules')}
function identityGuestLabel(g){return String(g.displayName||g.username||g.email||'Unnamed Guest')}
function identityUserLabel(u){return String(u.displayName||u.globalProfile?.username||u.email||'Permanent user')}
function identityLocationLabel(row){return row?.lastNetwork?.prettyLocation||row?.lastNetwork?.geo?.pretty||''}
function networkRowsHtml(rows=[]){if(!rows.length)return '<div class="empty">No network observations recorded yet.</div>';return `<table class="ip-table"><thead><tr><th>Approx. location</th><th>Network</th><th>IP</th><th>Last seen</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.prettyLocation||r.geo?.pretty||'Location unavailable')}</b>${r.geo?.isp?`<br><small>${esc(r.geo.isp)}${r.geo.asn?` · ${esc(r.geo.asn)}`:''}</small>`:''}</td><td>${esc(r.networkLabel||'—')}</td><td><code>${esc(r.displayIp||r.ip||'—')}</code><br><small>${esc(r.source||'')}</small></td><td>${esc(fmt(r.lastSeen))}</td></tr>`).join('')}</tbody></table>`}
function renderGeoStatus(){const g=identityState.geo||{},set=g.settings||{},obs=g.requestObservation||{};if($('#geoRemoteEnabled'))$('#geoRemoteEnabled').checked=set.remoteLookupEnabled!==false;if($('#geoStatus'))$('#geoStatus').innerHTML=`${set.remoteLookupEnabled!==false?'Approximate public-IP enrichment is enabled.':'Remote geolocation is disabled; LOOM will show only location hints supplied by the hosting/proxy layer.'} Cached locations: <b>${esc(g.cachedLocations||0)}</b>. <b>Location never counts as identity overlap.</b> ${obs.source?`<br>Network detector: <b>${esc(obs.version||'IP')}</b> via <code>${esc(obs.source)}</code> · ${obs.public?'public address available':'private/proxy address only'}${obs.networkLabel?` · ${esc(obs.networkLabel)}`:''}.`:''} ${set.remoteLookupEnabled!==false?'Admin detail lookups use the configured public-IP provider only when needed; directory lists stay cache/header-only for speed.':''}`}
function cleanupUserLabel(u){return u?.displayName||u?.globalProfile?.displayName||u?.email||u?.userId||'Permanent account'}
function cleanupOptions(){return {scope:$('#identityCleanupScope')?.value||'both',projectData:!!$('#cleanupProjectData')?.checked,activity:!!$('#cleanupActivity')?.checked,referrals:!!$('#cleanupReferrals')?.checked,continuity:!!$('#cleanupContinuity')?.checked,media:!!$('#cleanupMedia')?.checked,audit:!!$('#cleanupAudit')?.checked,attachedGuests:!!$('#cleanupAttachedGuests')?.checked}}
function renderIdentityMediaHygiene(){const m=cleanupState.status?.orphanMedia||{},n=Number(m.orphanCount||0),el=$('#identityMediaHygieneStatus');if(!el)return;el.innerHTML=n?`<b>${n}</b> provably orphaned identity-media item${n===1?'':'s'} · ${esc(m.formattedBytes||((m.orphanBytes||0)+' bytes'))}. These files have no surviving canonical owner record.`:'No provably orphaned identity media detected.'}
async function scanIdentityMedia(){try{const r=await identityCleanupPost({action:'media-audit'});cleanupState.status={...(cleanupState.status||{}),orphanMedia:r.orphanMedia};renderIdentityMediaHygiene();toastInfo(`${r.orphanMedia?.orphanCount||0} orphan media item(s) found.`,'Identity media scan')}catch(e){toastErr(e.message)}}
async function sweepIdentityMedia(){const phrase=prompt('This deletes only identity media that no longer has a surviving canonical owner. Type SWEEP ORPHAN IDENTITY MEDIA to continue.','');if(phrase!=='SWEEP ORPHAN IDENTITY MEDIA')return;try{const r=await identityCleanupPost({action:'media-reconcile',confirmPhrase:phrase});cleanupState.status={...(cleanupState.status||{}),orphanMedia:r.orphanMedia};renderIdentityMediaHygiene();toastOk(`${r.removed?.count||0} orphan media item(s) removed.`,'Identity media cleaned')}catch(e){toastErr(e.message)}}
function renderCleanupControls(){const kind=$('#identityCleanupKind')?.value||'guest-one',subject=$('#identityCleanupSubject'),wrap=$('#identityCleanupSubjectWrap'),owner=cleanupState.status?.systemOwner||{},db=!!cleanupState.status?.databaseReady;if($('#identityCleanupOwner'))$('#identityCleanupOwner').innerHTML=`<span class="pill">System Owner protected: ${esc(owner.userId||owner.clientId||'bootstrap owner')}</span><span class="pill">SQL ${db?'connected':'not connected'}</span><span class="pill">Legacy orphan clients: ${esc(cleanupState.status?.orphanClients||0)}</span>`;const needs=kind==='guest-one'||kind==='user-one';wrap?.classList.toggle('hidden',!needs);if(subject&&needs){const rows=kind==='guest-one'?(identityState.guests||[]):(identityState.users||[]);subject.innerHTML=rows.map(r=>kind==='guest-one'?`<option value="${esc(r.guestId)}" ${r.systemOwner?'disabled':''}>${esc(r.displayName||r.username||r.guestId)} · ${esc(r.guestId)}${r.systemOwner?' · SYSTEM OWNER · PROTECTED':''}</option>`:`<option value="${esc(r.userId)}" ${r.systemOwner?'disabled':''}>${esc(cleanupUserLabel(r))} · ${esc(r.email||r.userId)}${r.systemOwner?' · SYSTEM OWNER · PROTECTED':''}</option>`).join('')||'<option value="">No matching identities</option>'}if($('#identityCleanupScope')&&!db&&$('#identityCleanupScope').value==='both')$('#identityCleanupScope').value='local';cleanupState.preview=null;if($('#identityCleanupExecute'))$('#identityCleanupExecute').disabled=true;if($('#identityCleanupPreviewOut'))$('#identityCleanupPreviewOut').textContent='Preview a deletion before anything can be removed.'}
function cleanupSubjectId(){const kind=$('#identityCleanupKind')?.value||'';return (kind==='guest-one'||kind==='user-one')?($('#identityCleanupSubject')?.value||''):''}
function renderCleanupPreview(p){const c=p.counts||{},flags=p.flags||{};$('#identityCleanupPreviewOut').innerHTML=`<b>Nothing deleted yet.</b><br>Target: <code>${esc(p.kind)}</code> · storage: <b>${esc(p.scope)}</b><br>Permanent users: <b>${esc(c.permanentUsers||0)}</b> · Guest Identities: <b>${esc(c.guestIdentities||0)}</b> · browser clients: <b>${esc(c.browserClients||0)}</b> · legacy orphans: <b>${esc(c.orphanClients||0)}</b> · guest profiles: <b>${esc(c.guestProfiles||0)}</b><br>Data: ${['projectData','activity','referrals','continuity','media','audit'].filter(k=>flags[k]).map(k=>esc(k)).join(', ')||'core identity only'}${flags.attachedGuests?'<br><b>Attached Guest Histories will also be deleted.</b>':''}${(p.warnings||[]).length?`<hr>${p.warnings.map(x=>`⚠ ${esc(x)}`).join('<br>')}`:''}<hr>Execution phrase: <code>${esc(p.confirmPhrase||'')}</code>`;$('#identityCleanupExecute').disabled=false}
async function previewIdentityCleanup(){try{$('#identityCleanupMsg').textContent='Building deletion preview…';const r=await identityCleanupPost({action:'preview',kind:$('#identityCleanupKind').value,subjectId:cleanupSubjectId(),options:cleanupOptions()});cleanupState.preview=r.plan;renderCleanupPreview(r.plan);$('#identityCleanupMsg').textContent='Preview complete. No data changed.'}catch(e){cleanupState.preview=null;$('#identityCleanupExecute').disabled=true;$('#identityCleanupMsg').textContent=e.message}}
async function executeIdentityCleanup(){const p=cleanupState.preview;if(!p)return;const phrase=prompt(`PERMANENT deletion cannot be undone.\n\nType exactly:\n${p.confirmPhrase}`,'');if(phrase!==p.confirmPhrase){$('#identityCleanupMsg').textContent='Deletion cancelled; confirmation phrase did not match.';return}if(!confirm('Final confirmation: permanently delete the previewed identity data now?'))return;try{$('#identityCleanupExecute').disabled=true;$('#identityCleanupMsg').textContent='Deleting selected identity data…';const r=await identityCleanupPost({action:'execute',kind:p.kind,subjectId:p.subjectId||'',options:{...p.flags,scope:p.scope},confirmPhrase:phrase});$('#identityCleanupMsg').textContent=r.message||'Permanent deletion complete.';cleanupState.preview=null;if(r.ownerReset){location.href='../home/';return}await loadIdentities();toastOk('Selected identity data was permanently deleted.','Identity cleanup')}catch(e){$('#identityCleanupExecute').disabled=false;$('#identityCleanupMsg').textContent=e.message;toastErr(e.message)}}

// v0.15.58 canonical Users directory: one person list, optionally project-focused.
function unifiedAvatarUrl(person,project=''){if(!person?.subjectType||!person?.subjectId)return '../assets/loom-default-avatar.svg';project=String(project||'').trim();const scoped=project!=='';const version=scoped?(person.projectAvatarVersion||person.avatar?.version||person.avatarVersion||'0.15.58'):(person.avatarVersion||'0.15.58');const q=new URLSearchParams({action:'image',scope:scoped?'project':'global',subjectType:person.subjectType,subjectId:person.subjectId,v:version});if(scoped)q.set('project',project);const clientId=scoped?(person.projectAvatarClientId||person.avatar?.clientId||person.avatarClientId):person.avatarClientId;if(clientId)q.set('clientId',clientId);return `../api/profile-avatar.php?${q.toString()}`}
function unifiedScopeProject(){return $('#usersScope')?.value||''}
function renderIdentityList(){
  const box=$('#identityList');if(!box)return;const q=($('#identitySearch')?.value||'').trim().toLowerCase(),filter=$('#identityKindFilter')?.value||'all';
  const rows=(usersState||[]).filter(x=>filter==='all'||(filter==='permanent'&&x.kind==='permanent')||(filter==='guest'&&x.kind==='guest')||(filter==='required'&&x.permanentRequired)||(filter==='banned'&&(x.globalBanned||x.projectBanned))).filter(x=>!q||JSON.stringify(x).toLowerCase().includes(q));
  const scopeProject=unifiedScopeProject();box.innerHTML=rows.map(x=>{const active=selectedDirectory.kind===x.subjectType&&selectedDirectory.id===x.subjectId,loc=identityLocationLabel(x),bad=x.globalBanned?' · 🚫 LOOM BANNED':(x.projectBanned?' · 🚫 PROJECT BANNED':'');return `<button class="user-row ${active?'active':''}" data-directory-kind="${esc(x.subjectType)}" data-directory-id="${esc(x.subjectId)}"><div class="user-row-main"><img class="user-row-avatar" src="${unifiedAvatarUrl(x,scopeProject)}" onerror="this.onerror=null;this.src='../assets/loom-default-avatar.svg'"><div class="user-row-copy"><strong>${esc(x.displayName||x.email||x.subjectId)}</strong><small>${x.kind==='permanent'?'Permanent account':'Guest Identity'} · ${scopeProject?'Project avatar':'LOOM-wide avatar'}${x.systemOwner?' · System Owner':x.loomAdmin?' · LOOM Admin':''}${x.permanentRequired?' · ⚠ permanent account required':''}${bad}</small><small>${x.email?`${esc(x.email)} · `:''}${esc(x.projectCount||0)} project${Number(x.projectCount||0)===1?'':'s'} · ${esc(x.clientCount||0)} client${Number(x.clientCount||0)===1?'':'s'}${loc?` · ${esc(loc)}`:''}</small></div></div></button>`}).join('')||'<div class="empty">No people match this directory filter.</div>';
  box.querySelectorAll('[data-directory-kind]').forEach(b=>b.onclick=()=>loadUnifiedUserDetail(b.dataset.directoryKind,b.dataset.directoryId,unifiedScopeProject()));
}
function unifiedProjectOptions(d,selected=''){const all=new Map((projectsState||[]).map(p=>[p.slug,p.name||p.slug]));for(const p of (d.projects||[]))all.set(p.project,p.name||p.project);return [...all.entries()].map(([slug,name])=>`<option value="${esc(slug)}" ${slug===selected?'selected':''}>${esc(name)} · ${esc(slug)}</option>`).join('')}
function unifiedProjectPanel(d,p){if(!p)return '<div class="empty">Choose a project to inspect this person’s project-specific identity, activity and moderation.</div>';const i=p.identity||{},a=p.activity||{},av=p.avatar||{},isAdmin=['system-owner','loom-admin','project-admin'].includes(p.role),avatarMode=av.mode||i.avatarMode||'auto',avatarLabel=av.label||({custom:'Project custom avatar',global:'Global avatar inherited','project-default':'Project default avatar',auto:'Automatic project avatar'}[avatarMode]||avatarMode);return `<div class="user-project-card"><div class="user-project-identity-head"><img class="project-identity-avatar" src="${unifiedAvatarUrl({...d,avatar:av,projectAvatarVersion:av.version,projectAvatarClientId:av.clientId},p.project)}" onerror="this.onerror=null;this.src='../assets/loom-default-avatar.svg'"><div class="project-identity-copy"><div class="eyebrow">PROJECT-SPECIFIC IDENTITY</div><strong>${esc(i.effectiveUsername||i.username||d.displayName||'—')}</strong><small>${esc(p.name||p.project)} · ${esc(avatarLabel)}</small><small>Avatar mode: <code>${esc(avatarMode)}</code>${av.customAvailable?' · custom image stored':''}${av.legacyFallback?' · migrated/legacy fallback':''}</small></div></div><div class="status-row"><span class="pill">${esc(p.role||'member')}</span>${p.banned?'<span class="pill bad">Banned from project</span>':'<span class="pill">Allowed in project</span>'}<span class="pill">${esc(a.eventCount||0)} events</span><span class="pill">${esc(a.sessionCount||0)} sessions</span></div><div class="detail-grid"><div class="info"><b>Project identity</b><strong>${esc(i.effectiveUsername||i.username||d.displayName||'—')}</strong></div><div class="info"><b>Username mode</b>${esc(i.usernameMode||'global/default')}</div><div class="info"><b>Avatar mode</b>${esc(avatarMode)}</div><div class="info"><b>Avatar source</b>${esc(avatarLabel)}</div><div class="info"><b>First activity</b>${esc(fmt(a.firstSeen))}</div><div class="info"><b>Last activity</b>${esc(fmt(a.lastSeen))}</div></div><div class="buttons"><button class="${p.banned?'secondary':'danger'}" id="toggleProjectBan">${p.banned?'Remove project ban':'Ban from this project'}</button>${!d.systemOwner?`<button class="secondary" id="toggleProjectAdmin">${isAdmin?'Revoke Project Admin':'Make Project Admin'}</button>`:''}</div><p style="margin-top:8px">This picture is the avatar LOOM resolves for this person <b>inside ${esc(p.name||p.project)}</b>. It can be a project custom avatar, project default, inherited global avatar, or LOOM default depending on that project identity’s avatar mode. A project ban affects only this project.</p></div>`}
function renderUnifiedUserDetail(d){
  selectedDirectory={kind:d.subjectType,id:d.subjectId};selectedGuestId=d.subjectType==='guest'?d.subjectId:null;renderIdentityList();const box=$('#identityDetail');if(!box)return;const focus=d.focusedProject?.project||unifiedScopeProject()||'',p=d.focusedProject||null,guests=d.guestHistories||[],cont=d.continuity||{},refs=d.referrals||{},net=d.ipHistory||[],account=d.account||{},gp=d.globalProfile||{},guest=d.guestIdentity||{},authority=d.authority||{},lineage=d.clientLineage||[],aliases=[...new Set(lineage.flatMap(x=>x.aliases||[]).filter(x=>x&&x!==d.displayName))];
  const status=`<span class="pill">${d.kind==='permanent'?'Permanent account':'Guest Identity'}</span>${d.systemOwner?'<span class="pill">System Owner</span>':d.loomAdmin?'<span class="pill">LOOM Admin</span>':''}${d.globalBan?.banned?'<span class="pill bad">Banned from LOOM</span>':''}${cont.permanentRequired?'<span class="pill warn">Permanent account required</span>':''}`;
  box.innerHTML=`<div class="detail-head"><img class="avatar" src="${unifiedAvatarUrl(d,focus)}" onerror="this.onerror=null;this.src='../assets/loom-default-avatar.svg'"><div><div class="eyebrow">${d.kind==='permanent'?'PERMANENT ACCOUNT':'GUEST IDENTITY'}</div><h2>${esc(d.displayName||d.email||d.subjectId)}</h2><p>${d.email?`${esc(d.email)} · `:''}<code>${esc(d.subjectId)}</code></p><div class="status-row">${status}</div></div></div><div class="detail-grid"><div class="info"><b>Linked browser clients</b><strong>${esc((d.clients||[]).length)}</strong></div><div class="info"><b>Projects participated</b><strong>${esc((d.projects||[]).length)}</strong></div><div class="info"><b>Guest Histories</b><strong>${esc(guests.length)}</strong></div><div class="info"><b>Storage</b>${esc(d.storageMode||'durable-local')}</div><div class="info"><b>Referral links</b><strong>${esc(refs.shareLinks||0)}</strong></div><div class="info"><b>Successful referrals</b><strong>${esc(refs.referrals||0)}</strong></div></div>
  <div class="module" style="margin-top:14px"><div class="eyebrow">CANONICAL IDENTITY RECORDS</div><h2>${d.kind==='permanent'?'Permanent account + linked history':'Guest Identity + browser lineage'}</h2><div class="detail-grid"><div class="info"><b>Canonical subject</b><code>${esc(d.subjectType)}:${esc(d.subjectId)}</code></div><div class="info"><b>Global display name</b>${esc(gp.displayName||gp.username||d.displayName||'—')}</div><div class="info"><b>Global avatar mode</b>${esc(gp.avatarMode||'emergency-fallback')}</div><div class="info"><b>Created</b>${esc(fmt(account.createdAt||guest.createdAt))}</div><div class="info"><b>Updated / last identity change</b>${esc(fmt(account.updatedAt||guest.updatedAt||gp.updatedAt))}</div><div class="info"><b>Privilege</b>${esc(d.privilege||'Guest')}</div></div>${(d.clients||[]).length?`<div class="setup"><b>Proven linked browser clients</b><br>${d.clients.map(cid=>`<code>${esc(cid)}</code>`).join(' &nbsp; ')}</div>`:'<div class="empty">No linked browser client is stored for this identity.</div>'}${aliases.length?`<div class="setup" style="margin-top:10px"><b>Historical browser identity aliases</b><br>${aliases.map(x=>`<span class="pill">${esc(x)}</span>`).join(' ')}<p style="margin-top:8px">These are older display labels observed on proven browser/account lineage. They are history, not separate current users.</p></div>`:''}</div>
  ${d.systemOwner?`<div class="module" style="margin-top:14px;border:2px solid #1f8f4f"><div class="eyebrow">SYSTEM OWNER · INSTALLATION AUTHORITY</div><h2>This is LOOM's root owner identity</h2><div class="status-row"><span class="pill">System Owner</span><span class="pill">Root authority</span><span class="pill">${authority.accountBound?'Permanent-account backed':'Browser-bootstrap backed'}</span></div><div class="detail-grid"><div class="info"><b>Owner user</b><code>${esc(authority.ownerUserId||'Not bound yet')}</code></div><div class="info"><b>Bootstrap client</b><code>${esc(authority.ownerClientId||'—')}</code></div><div class="info"><b>Bootstrap method</b>${esc(authority.bootstrapMethod||'legacy/bootstrap')}</div><div class="info"><b>Authority role</b><strong>System Owner</strong></div></div>${!authority.accountBound?`<div class="setup"><b>Owner is still browser-backed.</b><br>Sign in to or create the intended permanent LOOM account on the protected owner browser. LOOM will bind that verified account to the System Owner pointer automatically; it will not guess from names.</div>`:''}<div class="buttons" style="margin-top:10px"><button class="save" id="openAccessManager">Open System Owner / Access Manager</button></div></div>`:''}
  <div class="module" style="margin-top:14px"><div class="eyebrow">NETWORK &amp; LOCATION</div><h2>Observed network context</h2><p>Approximate geography is for Admin context only. City/region/country never authenticates, merges, or bans a person. Exact shared public IPv4 and bounded IPv6 /64/device evidence can trigger the guest ambiguity gate.</p>${networkRowsHtml(net)}</div>
  <div class="module" style="margin-top:14px"><div class="eyebrow">CONTINUITY &amp; REFERRALS</div><h2>Identity lineage</h2><div class="detail-grid"><div class="info"><b>Continuity clusters</b>${esc((cont.clusterIds||[]).join(', ')||'—')}</div><div class="info"><b>Guest ambiguity locks</b>${esc((cont.guestLocks||[]).length)}</div><div class="info"><b>Referred by</b>${esc(refs.referredBy?.username||'—')}</div><div class="info"><b>Referral clicks</b>${esc(refs.clicks||0)}</div></div>${guests.length?`<div class="setup"><b>Attached Guest Histories</b><br>${guests.map(g=>`<button class="reset" data-open-history="${esc(g.guestId)}">${esc(g.guestId)}</button>`).join(' ')}</div>`:''}</div>
  <div class="module" style="margin-top:14px"><div class="eyebrow">PROJECT INSPECTOR</div><h2>Per-project identity &amp; controls</h2><div class="field"><label>Inspect project</label><select id="userDetailProject"><option value="">Choose project…</option>${unifiedProjectOptions(d,focus)}</select></div><div id="userProjectInspector">${unifiedProjectPanel(d,p)}</div></div>
  <div class="ban-zone"><div class="eyebrow">GLOBAL LOOM MODERATION</div><h2>LOOM-wide access</h2><p>Global ban blocks this identity from LOOM project access everywhere while retaining the account and data. Use project bans above when only one project should be blocked.</p><div class="buttons"><button id="toggleGlobalBan" class="${d.globalBan?.banned?'secondary':'danger'}" ${d.systemOwner?'disabled':''}>${d.globalBan?.banned?'Remove global LOOM ban':'Ban from LOOM globally'}</button>${d.kind==='permanent'&&!d.systemOwner?`<button id="toggleLoomAdmin" class="secondary">${d.loomAdmin?'Revoke LOOM Admin':'Make LOOM Admin'}</button>`:''}</div></div>
