async function loadUnifiedUserDetail(type,id,project=''){try{const r=await usersPost({action:'detail',subjectType:type,subjectId:id,project});renderUnifiedUserDetail(r.user)}catch(e){$('#identityDetail').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
async function loadPermanentIdentityDetail(userId){return loadUnifiedUserDetail('user',userId,unifiedScopeProject())}
async function loadIdentityDetail(guestId){return loadUnifiedUserDetail('guest',guestId,unifiedScopeProject())}
async function loadIdentities(keepDetail=true){
  const refresh=$('#identityRefresh');if(refresh){refresh.disabled=true;refresh.classList.add('is-loading');refresh.setAttribute('aria-busy','true')}
  try{
    const focus=unifiedScopeProject();
    const r=await usersPost({action:'list',project:focus});
    usersState=r.users||[];
    identityState={
      users:usersState.filter(x=>x.kind==='permanent').map(x=>({...x,userId:x.subjectId})),
      guests:usersState.filter(x=>x.kind==='guest').map(x=>({...x,guestId:x.subjectId,status:'unattached',updatedAt:x.lastSeen})),
      geo:r.geo||identityState.geo
    };
    const count=$('#userDirectoryCount');
    if(count)count.textContent=`${r.total||0} user${Number(r.total||0)===1?'':'s'} · ${focus?((projectsState||[]).find(x=>x.slug===focus)?.name||focus):'Global LOOM'}`;
    renderIdentityList();renderGeoStatus();
    try{cleanupState.status=await identityCleanupPost({action:'status'});$('#identityCleanupCard')?.classList.remove('hidden');renderCleanupControls();renderIdentityMediaHygiene()}catch(e){$('#identityCleanupCard')?.classList.add('hidden')}
    if(keepDetail&&selectedDirectory.id){
      const still=usersState.find(x=>x.subjectType===selectedDirectory.kind&&x.subjectId===selectedDirectory.id);
      if(still)await loadUnifiedUserDetail(selectedDirectory.kind,selectedDirectory.id,focus);
      else{$('#identityDetail').innerHTML='<div class="empty">Select a person.</div>';selectedDirectory={kind:null,id:null}}
    }
  }catch(e){$('#identityList').innerHTML=`<div class="empty">${esc(e.message)}</div>`}
  finally{if(refresh){refresh.disabled=false;refresh.classList.remove('is-loading');refresh.removeAttribute('aria-busy')}}
}

