  $('#grantProjectAccess').disabled=!a.canManageProject;
  $('#loomAdminList').innerHTML=(a.loomAdmins||[]).length?(a.loomAdmins||[]).map(x=>`<div style="display:flex;justify-content:space-between;gap:8px;align-items:center;padding:7px 0;border-bottom:1px solid #e8eee9"><span><b>${esc(x.label||x.userId)}</b><br><small>${esc(x.email||x.userId)}</small></span>${a.canManageLoomAdmins?`<button class="danger" data-revoke-loom="${esc(x.userId)}">Revoke</button>`:''}</div>`).join(''):'No secondary LOOM Admins.';
  $('#projectAccessList').innerHTML=!hasProject?'Create or import a project before assigning Project Admin access.':((a.projectGrants||[]).length?(a.projectGrants||[]).map(x=>`<div style="display:flex;justify-content:space-between;gap:8px;align-items:center;padding:7px 0;border-bottom:1px solid #e8eee9"><span><b>${esc(x.label)}</b> · ${x.role==='project-manager'?'Legacy Project Manager':'Project Admin'}<br><small>${esc(projectName)} · <code>${esc(project)}</code> · ${esc(x.type)} · ${esc(x.id)}</small></span><button class="danger" data-revoke-project-type="${esc(x.type)}" data-revoke-project-id="${esc(x.id)}">Revoke</button></div>`).join(''):`No Project Admin grants for <b>${esc(projectName)}</b>.`);
  const visPill=$('#projectVisibilityPill');if(visPill)visPill.textContent=visibility==='private'?'🔒 Private':'🌐 Public';
  const visBtn=$('#toggleProjectVisibility');if(visBtn){visBtn.textContent=visibility==='private'?'🌐 Make Public':'🔒 Make Private';visBtn.disabled=!a.canManageProjectVisibility;visBtn.hidden=!a.canManageProjectVisibility;}
  const privateControls=$('#privateAccessControls');if(privateControls)privateControls.classList.toggle('hidden',!a.canManagePrivateAccess);
  const privateGrant=$('#grantPrivateAccess');if(privateGrant)privateGrant.disabled=!a.canManagePrivateAccess;
  const viewRows=a.projectViewGrants||[];
  $('#privateAccessList').innerHTML=!a.canManagePrivateAccess?'Only the System Owner can grant or revoke access to private projects.':(viewRows.length?viewRows.map(x=>`<div style="display:flex;justify-content:space-between;gap:8px;align-items:center;padding:7px 0;border-bottom:1px solid #e8eee9"><span><b>${esc(x.label)}</b><br><small>Private project access · ${esc(x.type)}</small></span><button class="danger" data-revoke-private-type="${esc(x.type)}" data-revoke-private-id="${esc(x.id)}">Revoke</button></div>`).join(''):(visibility==='private'?'No explicit private-project access grants.':'No access grants are needed while this project is public.'));
  document.querySelectorAll('[data-revoke-loom]').forEach(b=>b.onclick=async()=>{if(!confirm('Revoke this secondary LOOM Admin?'))return;try{accessState=await accessPost({action:'revoke-loom-admin',userId:b.dataset.revokeLoom});renderAccess()}catch(e){$('#accessMsg').textContent=e.message}});
  document.querySelectorAll('[data-revoke-project-id]').forEach(b=>b.onclick=async()=>{if(!confirm(`Revoke this Project Admin grant from ${projectName}?`))return;try{accessState=await accessPost({action:'revoke-project',subjectType:b.dataset.revokeProjectType,subjectId:b.dataset.revokeProjectId});renderAccess()}catch(e){$('#accessMsg').textContent=e.message}});
  document.querySelectorAll('[data-revoke-private-id]').forEach(b=>b.onclick=async()=>{if(!confirm(`Revoke private access to ${projectName}?`))return;try{accessState=await accessPost({action:'revoke-project-view',subjectType:b.dataset.revokePrivateType,subjectId:b.dataset.revokePrivateId});renderAccess()}catch(e){$('#accessMsg').textContent=e.message}});
