async function loadAccess(){
  try{
    accessState=await accessPost({action:'status'});
    renderAccess(); // Existing project grants/role stay visible even if the optional chooser catalog is busy.
  }catch(e){$('#accessMsg').textContent=e.message;toastErr(e.message);return}
  const a=accessState?.access||accessState||{};
  if(!a.canManageProject&&!a.canManageLoomAdmins)return;
  if(accessSubjects.length&&Date.now()-accessSubjectsLoadedAt<=120000)return;
  try{
    const catalog=await accessPost({action:'catalog'});
    accessSubjects=Array.isArray(catalog.subjects)?catalog.subjects:[];
    accessSubjectsLoadedAt=Date.now();
    renderAccess();
    if($('#accessMsg')?.textContent?.includes('Grant chooser'))$('#accessMsg').textContent='';
  }catch(e){
    accessSubjectsLoadedAt=0;
    $('#accessMsg').textContent=`Existing access is shown. Grant chooser is temporarily unavailable: ${e.message}`;
  }
}
const EMAIL_EVENT_META={welcome:['Welcome email','Sent after a guest becomes a permanent account.'],passwordReset:['Password reset','Required for Forgot Password recovery.'],passwordChanged:['Password changed','Security confirmation after a password replacement.'],emailChanged:['Email changed','Confirms the permanent-account email was updated.'],referral:['Referral attributed','Notifies a permanent referrer when someone is attributed to their link.'],newSignIn:['New sign-in','Optional security notice; disabled by default to avoid noise.']};
function renderEmail(){const e=emailState?.email||{},c=e.settings||{},smtp=c.smtp||{},events=c.events||{},subjects=c.subjects||{};$('#emailEnabled').checked=!!c.enabled;$('#emailTransport').value=c.transport||'smtp';$('#emailSiteName').value=c.siteName||'LOOM';$('#emailBaseUrl').value=c.baseUrl||'';$('#emailFromName').value=c.fromName||'LOOM';$('#emailFromEmail').value=c.fromEmail||'';$('#emailReplyTo').value=c.replyTo||'';$('#emailFooter').value=c.footerText||'';$('#smtpHost').value=smtp.host||'';$('#smtpPort').value=smtp.port||587;$('#smtpEncryption').value=smtp.encryption||'starttls';$('#smtpTimeout').value=smtp.timeout||10;$('#smtpUsername').value=smtp.username||'';$('#smtpPassword').value='';$('#smtpPassword').placeholder=smtp.passwordSaved?'Password saved · leave blank to keep':'SMTP password';$('#smtpAuth').checked=smtp.auth!==false;$('#smtpCard').classList.toggle('hidden',(c.transport||'smtp')!=='smtp');$('#emailStatus').innerHTML=`<span class="pill ${e.ready?'':'warn'}">${e.ready?'Email ready':'Setup incomplete'}</span><span class="pill">${esc((c.transport||'smtp').toUpperCase())}</span><span class="pill ${c.enabled?'':'warn'}">${c.enabled?'Delivery enabled':'Delivery disabled'}</span>`;$('#emailChecks').innerHTML=(e.checks||[]).map(x=>`<div style="margin:5px 0"><b>${x.ok?'✓':'⚠'} ${esc(x.label)}</b></div>`).join('')+(e.probe?`<hr><b>${e.probe.ok?'✓':'⚠'} SMTP probe:</b> ${esc(e.probe.message||'')}`:'');$('#emailEvents').innerHTML=Object.entries(EMAIL_EVENT_META).map(([k,[name,help]])=>`<div class="module" style="padding:13px"><label class="field-check"><input type="checkbox" data-email-event="${esc(k)}" ${events[k]?'checked':''}><span><b>${esc(name)}</b><br><small style="color:#718078">${esc(help)}</small></span></label><div class="field"><label>Subject</label><input data-email-subject="${esc(k)}" type="text" value="${esc(subjects[k]||'')}"></div></div>`).join('');const rows=e.recent||[];$('#emailRecent').innerHTML=rows.length?rows.slice(0,30).map(r=>`<div style="display:grid;grid-template-columns:145px 120px minmax(130px,1fr) 80px;gap:8px;padding:6px 0;border-bottom:1px solid #e6eee8;font-size:10px"><span>${esc(fmt(r.createdAt))}</span><b>${esc(r.event||'email')}</b><span>${esc(r.to||'')}</span><span>${r.success?'✓ sent':r.skipped?'— skipped':'⚠ failed'}</span></div>`).join(''):'No email activity yet.'}
function readEmailSettings(){const events={},subjects={};document.querySelectorAll('[data-email-event]').forEach(x=>events[x.dataset.emailEvent]=!!x.checked);document.querySelectorAll('[data-email-subject]').forEach(x=>subjects[x.dataset.emailSubject]=x.value);return {enabled:$('#emailEnabled').checked,transport:$('#emailTransport').value,siteName:$('#emailSiteName').value,baseUrl:$('#emailBaseUrl').value,fromName:$('#emailFromName').value,fromEmail:$('#emailFromEmail').value,replyTo:$('#emailReplyTo').value,footerText:$('#emailFooter').value,smtp:{host:$('#smtpHost').value,port:Number($('#smtpPort').value||587),encryption:$('#smtpEncryption').value,timeout:Number($('#smtpTimeout').value||10),username:$('#smtpUsername').value,password:$('#smtpPassword').value,auth:$('#smtpAuth').checked},events,subjects}}
