function selectedProjectInfo(){const project=$('#project')?.value||'';return (projectsState||[]).find(x=>x.slug===project)||{slug:project,name:project}}
function syncSelectedProjectContext(){const info=selectedProjectInfo(),project=info.slug||'',appLink=$('#appLink');if(!project){if(appLink){appLink.href='#';appLink.removeAttribute('data-project');appLink.setAttribute('aria-disabled','true');appLink.textContent='No project selected'}return}const app=info.app_url||`../projects/${encodeURIComponent(project)}/app/?project=${encodeURIComponent(project)}`;if(appLink){appLink.href=app;appLink.dataset.project=project;appLink.removeAttribute('aria-disabled');appLink.textContent=`Open ${info.name||project}`;}if($('#pegLink'))$('#pegLink').href=`../pegboard/?project=${encodeURIComponent(project)}`;if($('#regLink'))$('#regLink').href=`../registry/?project=${encodeURIComponent(project)}`;const url=new URL(location.href);url.searchParams.set('project',project);history.replaceState(null,'',url);}
async function loadProjects(){const requested=new URLSearchParams(location.search).get('project')||'',j=await adminFetchJson(`../api/projects.php?clientId=${encodeURIComponent(identity.clientId)}&_=${Date.now()}`,{},'Projects',4),sel=$('#project');projectsState=Array.isArray(j.projects)?j.projects:[];sel.innerHTML=projectsState.map(p=>`<option value="${esc(p.slug)}">${esc(p.name)}</option>`).join('')||'<option value="">No projects available</option>';const us=$('#usersScope');if(us){const keep=us.value;us.innerHTML='<option value="">Global LOOM · All users</option>'+projectsState.map(p=>`<option value="${esc(p.slug)}">Project · ${esc(p.name)}</option>`).join('');if([...us.options].some(o=>o.value===keep))us.value=keep;if(requested&&[...us.options].some(o=>o.value===requested))us.value=requested;}if(requested&&[...sel.options].some(o=>o.value===requested))sel.value=requested;if(!sel.value&&projectsState[0])sel.value=projectsState[0].slug;syncSelectedProjectContext();syncProjectScopedAvailability();if((j.project_warnings||[]).length)toastInfo(`${j.project_warnings.length} project${j.project_warnings.length===1?' was':'s were'} skipped during discovery. Other projects remain available.`,'Project discovery');sel.onchange=async()=>{syncSelectedProjectContext();currentStatus=await post({action:'status',claim:false,project:sel.value||''});selected=null;selectedGuestId=null;selectedDirectory={kind:null,id:null};if($('#identityDetail'))$('#identityDetail').innerHTML='<div class="empty">Select a person.</div>';$('#accessMsg').textContent='';syncProjectScopedAvailability();if(tab==='project'&&hasSelectedProject())await loadSettings();else if(tab==='users'){await loadIdentities();}else if(tab==='access')await loadAccess()};return true}
async function loadSettings(){if(!syncProjectScopedAvailability())return;const project=$('#project').value;syncSelectedProjectContext();state=await post({action:'settings',project});renderProjectProfile();renderProjectPresentation();renderModuleControl();renderModules();decorateProjectStaticCards()}
$('#appLink')?.addEventListener('click',e=>{e.preventDefault();syncSelectedProjectContext();const href=$('#appLink').href;if(href)location.href=href});
function showTab(next){if(next==='identities')next='users';tab=next;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));$('#loomSettingsPanel').classList.toggle('active',tab==='loom');$('#projectSettingsPanel').classList.toggle('active',tab==='project');$('#usersPanel').classList.toggle('active',tab==='users');$('#accessPanel').classList.toggle('active',tab==='access');$('#emailPanel').classList.toggle('active',tab==='email');$('#databasePanel').classList.toggle('active',tab==='database');$('#projectChooser').classList.toggle('hidden',!(tab==='project'||tab==='access'));const hasProject=syncProjectScopedAvailability();if(tab==='loom')loadGlobalSettings();if(tab==='project'&&hasProject)loadSettings();if(tab==='users')loadIdentities();if(tab==='access')loadAccess();if(tab==='email')loadEmail();if(tab==='database')loadDb()}
$('#grantLoomAdmin')?.addEventListener('click',async()=>{const userId=$('#loomAdminSubject').value;if(!userId)return;try{accessState=await accessPost({action:'grant-loom-admin',userId});renderAccess();toastOk('Secondary LOOM Admin granted.','Access updated')}catch(e){$('#accessMsg').textContent=e.message;toastErr(e.message)}});
$('#grantProjectAccess')?.addEventListener('click',async()=>{const raw=$('#projectAccessSubject').value,project=$('#project').value;if(!raw||!project)return;const [subjectType,...rest]=raw.split(':'),subjectId=rest.join(':');const info=selectedProjectInfo();if(!confirm(`Grant Project Admin access to ${info.name||project}? This grant applies only to this project.`))return;try{accessState=await accessPost({action:'grant-project',subjectType,subjectId,role:'project-admin'});renderAccess();toastOk(`Project Admin granted for ${info.name||project}.`,'Access updated')}catch(e){$('#accessMsg').textContent=e.message;toastErr(e.message)}});$('#toggleProjectVisibility')?.addEventListener('click',async()=>{const project=$('#project').value;if(!project)return;const a=accessState?.access||accessState||{},current=String(a.projectVisibility||'public').toLowerCase()==='private'?'private':'public',next=current==='private'?'public':'private',info=selectedProjectInfo();if(!confirm(`${next==='private'?'Make':'Restore'} ${info.name||project} ${next==='private'?'PRIVATE':'PUBLIC'}? ${next==='private'?'Regular users will no longer see the project unless explicitly granted access.':'The project will become visible to all LOOM users.'}`))return;try{accessState=await accessPost({action:'set-project-visibility',visibility:next});renderAccess();toastOk(`${info.name||project} is now ${next}.`,'Project visibility')}catch(e){$('#accessMsg').textContent=e.message;toastErr(e.message)}});
$('#grantPrivateAccess')?.addEventListener('click',async()=>{const raw=$('#privateAccessSubject').value,project=$('#project').value;if(!raw||!project)return;const [subjectType,...rest]=raw.split(':'),subjectId=rest.join(':'),info=selectedProjectInfo();if(!confirm(`Grant access to private project ${info.name||project}?`))return;try{accessState=await accessPost({action:'grant-project-view',subjectType,subjectId});renderAccess();toastOk(`Private access granted for ${info.name||project}.`,'Access updated')}catch(e){$('#accessMsg').textContent=e.message;toastErr(e.message)}});
$('#moduleControlSearch')?.addEventListener('input',renderModuleControl);document.querySelectorAll('.tab').forEach(x=>x.onclick=()=>showTab(x.dataset.tab));$('#identitySearch').oninput=renderIdentityList;$('#identityKindFilter')?.addEventListener('change',renderIdentityList);$('#identityRefresh').onclick=()=>loadIdentities();$('#usersScope')?.addEventListener('change',async()=>{const scope=$('#usersScope').value||'',url=new URL(location.href);if(scope){url.searchParams.set('project',scope);if([...($('#project')?.options||[])].some(o=>o.value===scope)){$('#project').value=scope;syncSelectedProjectContext()}}else url.searchParams.delete('project');history.replaceState(null,'',url);selectedDirectory={kind:null,id:null};$('#identityDetail').innerHTML='<div class="empty">Select a person.</div>';await loadIdentities(false)});$('#geoSave')?.addEventListener('click',async()=>{const ok=confirmPhrase('Save Admin IP-geolocation enrichment settings?');if(!ok)return;try{const r=await identitiesPost({action:'geo-settings-save',settings:{remoteLookupEnabled:!!$('#geoRemoteEnabled')?.checked},confirmPhrase:ok});identityState.geo=r.geo||identityState.geo;renderGeoStatus();toastOk('Network location settings saved.','Users')}catch(e){toastErr(e.message)}});$('#geoClearCache')?.addEventListener('click',async()=>{const ok=confirmPhrase('Clear the cached approximate IP-location labels? Identity/network history itself will stay intact.');if(!ok)return;try{const r=await identitiesPost({action:'geo-cache-clear',confirmPhrase:ok});identityState.geo=r.geo||identityState.geo;renderGeoStatus();toastOk(`${r.cleared||0} cached locations cleared.`,'Users')}catch(e){toastErr(e.message)}});$('#identityCleanupKind')?.addEventListener('change',renderCleanupControls);$('#identityCleanupSubject')?.addEventListener('change',()=>{cleanupState.preview=null;$('#identityCleanupExecute').disabled=true});$('#identityCleanupScope')?.addEventListener('change',()=>{cleanupState.preview=null;$('#identityCleanupExecute').disabled=true});document.querySelectorAll('#identityCleanupCard input[type=checkbox]').forEach(x=>x.addEventListener('change',()=>{cleanupState.preview=null;$('#identityCleanupExecute').disabled=true;$('#identityCleanupPreviewOut').textContent='Options changed. Preview again before deletion.'}));$('#identityCleanupPreview')?.addEventListener('click',previewIdentityCleanup);$('#identityCleanupExecute')?.addEventListener('click',executeIdentityCleanup);$('#identityMediaScan')?.addEventListener('click',scanIdentityMedia);$('#identityMediaSweep')?.addEventListener('click',sweepIdentityMedia);$('#emailTransport')?.addEventListener('change',()=>$('#smtpCard')?.classList.toggle('hidden',$('#emailTransport').value!=='smtp'));$('#emailSave')?.addEventListener('click',async()=>{try{emailState=await emailPost({action:'save',settings:readEmailSettings()});renderEmail();$('#emailMsg').textContent=emailState.message||'Email settings saved.';toastOk('System email settings saved.','Email')}catch(e){$('#emailMsg').textContent=e.message;toastErr(e.message)}});$('#emailProbe')?.addEventListener('click',async()=>{try{$('#emailMsg').textContent='Checking connection…';emailState=await emailPost({action:'probe'});renderEmail();$('#emailMsg').textContent=emailState.email?.probe?.message||'Check complete.'}catch(e){$('#emailMsg').textContent=e.message}});$('#emailTest')?.addEventListener('click',async()=>{try{const to=$('#emailTestTo').value;if(!to)throw new Error('Enter a test recipient.');$('#emailMsg').textContent='Sending test…';emailState=await emailPost({action:'send-test',to});renderEmail();$('#emailMsg').textContent=emailState.message||'Test email sent.';toastOk('Test email accepted by the configured transport.','Email')}catch(e){$('#emailMsg').textContent=e.message;toastErr(e.message)}});$('#dbSave').onclick=async()=>{try{dbState=await dbPost({action:'configure',config:{host:$('#dbHost').value,port:Number($('#dbPort').value||3306),database:$('#dbName').value,username:$('#dbUser').value,password:$('#dbPass').value}});$('#dbMsg').textContent=dbState.message;renderDb()}catch(e){$('#dbMsg').textContent=e.message}};$('#dbInit').onclick=async()=>{try{dbState=await dbPost({action:'initialize'});$('#dbMsg').textContent=dbState.message;renderDb()}catch(e){$('#dbMsg').textContent=e.message}};$('#dbMigrate').onclick=async()=>{try{dbState=await dbPost({action:'migrate'});$('#dbMsg').textContent=`${dbState.message} ${JSON.stringify(dbState.migrated)}`;renderDb()}catch(e){$('#dbMsg').textContent=e.message}};$('#integrityScan').onclick=scanIntegrity;$('#integrityBackup').onclick=async()=>{try{const r=await dbPost({action:'integrity-backup'});$('#integrityMsg').textContent=`Snapshot ${r.backup.backupId} created on the protected server storage.`}catch(e){$('#integrityMsg').textContent=e.message}};$('#integrityRepair').onclick=async()=>{const confirmText=prompt('Safe Repair will create a database snapshot first and reconcile known identity mappings. Type CONFIRM to continue.','');if(confirmText!=='CONFIRM')return;try{const r=await dbPost({action:'integrity-repair',confirm:'CONFIRM'});$('#integrityMsg').textContent=`Repair complete. Backup: ${r.repair.backup.backupId}. Actions: ${(r.repair.actions||[]).join(', ')||'none needed'}`;renderIntegrity(r.repair.scan)}catch(e){$('#integrityMsg').textContent=e.message}};
(async()=>{try{const qs=new URLSearchParams(location.search),requestedProject=qs.get('project')||'';currentStatus=await post({action:'status',claim:false,project:requestedProject});LoomIdentity.setPrivilege(identity.clientId,currentStatus.privilege);const globalAdmin=!!currentStatus.isAdmin;let projectDiscoveryReady=false,projectError=null;try{projectDiscoveryReady=await loadProjects()}catch(e){projectError=e;if(!globalAdmin)throw e;projectsState=[];const sel=$('#project');if(sel)sel.innerHTML='<option value="">Project discovery temporarily unavailable</option>';syncSelectedProjectContext();syncProjectScopedAvailability();toastErr(`Project discovery is temporarily unavailable: ${e.message}. Global Admin tools remain usable.`)}const selectedProject=$('#project')?.value||requestedProject;if(selectedProject)currentStatus=await post({action:'status',claim:false,project:selectedProject});const canonicalViewerName=String(currentStatus?.viewer?.globalDisplayName||currentStatus?.viewer?.username||identity.userLabel||'LOOM User').trim();if(canonicalViewerName&&canonicalViewerName!==identity.userLabel){LoomIdentity.setUserLabel(identity.clientId,canonicalViewerName);identity.userLabel=canonicalViewerName;window.LOOM_USER_LABEL=canonicalViewerName}$('#who').textContent=`${canonicalViewerName} · ${identity.clientId.slice(0,20)}… · ${currentStatus.projectRole||currentStatus.privilege}`;const caps=currentStatus.capabilities||[];document.querySelector('[data-tab="loom"]')?.classList.toggle('hidden',!globalAdmin);document.querySelector('[data-tab="email"]')?.classList.toggle('hidden',!globalAdmin);document.querySelector('[data-tab="database"]')?.classList.toggle('hidden',!globalAdmin);const hasProjects=projectsState.length>0;document.querySelector('[data-tab="project"]')?.classList.toggle('hidden',!globalAdmin&&!hasProjects);document.querySelector('[data-tab="users"]')?.classList.toggle('hidden',!globalAdmin&&(!hasProjects||!caps.includes('project.users')));document.querySelector('[data-tab="access"]')?.classList.toggle('hidden',!globalAdmin&&(!projectDiscoveryReady||!hasProjects||!caps.includes('project.access')));if(globalAdmin){await Promise.allSettled([loadGlobalSettings(),loadEmail(),loadDb()])}const requestedTab=(qs.get('tab')==='identities'?'users':qs.get('tab')),allowed=[...document.querySelectorAll('.tab:not(.hidden)')].map(x=>x.dataset.tab);const first=allowed.includes(requestedTab)?requestedTab:(globalAdmin?'loom':'project');showTab(first);if(projectError&&globalAdmin)$('#projectChooser')?.classList.add('hidden')}catch(e){document.body.innerHTML=`<div style="padding:40px;font-family:system-ui"><h1>Admin access failed</h1><p>${esc(e.message)}</p><a href="../home/">Return home</a></div>`}})();
</script><div id="loomShellFooter"></div><script src="../engine/loom-brand.js?v=0.15.75"></script><script src="../engine/identity.js?v=0.15.75"></script><script src="../engine/loom-global-profile.js?v=0.15.75"></script><script src="../engine/loom-toast.js?v=0.15.75"></script><script src="../engine/share-referrals.js?v=0.15.75"></script><script src="../engine/loom-shell.js?v=0.15.75"></script><script>(async()=>{if(!window.LoomShell)return;const ident=LoomIdentity.get('loom-admin');await LoomShell.mount({apiBase:'../api',identity:ident,project:new URLSearchParams(location.search).get('project')||'',pageTitle:"Admin",links:[{label:'LOOM Home',href:"../home/"}]})})();</script></body></html>
